INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (100101, 1, "2030/12/31 15:00:00", "ひより", "【物理】前衛で、敵前線を押し返す笑顔の元気娘。\n前衛に対して大ダメージを与えるユニオンバーストと、\n自身の攻撃力を強化するスキルを持つ攻撃役。", 7, 100101, 1, 0, "ヒヨリ", 1, 1, 100101, 0, 0, 200, 100101, 2.295, "2015/04/01 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (100201, 7, "2030/12/31 15:00:00", "ゆい", "【魔法】最後衛から、味方の回復と補助を行う魔法士。\n打たれ弱いが高い魔法攻撃力を持ち、ランクを上げると\n攻撃も補助もバランスよくこなせるようになる。", 7, 100201, 2, 0, "ユイ", 7, 1, 100201, 0, 0, 800, 100201, 2.27, "2015/04/01 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (100301, 4, "2030/12/31 15:00:00", "れい", "【物理】前衛で、一点突破で敵を討つ、孤高の剣士。\nユニオンバースト、スキル共に眼前の敵を倒す事に優れ、\n高火力の攻撃スキルを駆使して前線を押し上げる。", 7, 100301, 1, 0, "レイ", 4, 1, 100301, 0, 0, 250, 100301, 1.965, "2015/04/01 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (100401, 1, "2030/12/31 15:00:00", "みそぎ", "【物理】最前衛で、敵の物理攻撃を邪魔するいたずら娘。\n目の前の敵を暗闇状態にし、命中率を大幅に下げるほか、\n敵一体の物理攻撃力を下げるスキルを持つ。", 13, 100401, 1, 0, "ミソギ", 1, 1, 100401, 0, 0, 205, 100401, 2.17, "2015/04/01 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (100501, 2, "2030/12/31 15:00:00", "まつり", "【物理】前衛の、機敏な動きで敵をかき回す騎士見習い。\nユニオンバーストで相手の陣地の真ん中に飛び込み、\n自分の周囲を攻撃するスキルで相手を攻め立てる。", 2, 100501, 1, 0, "マツリ", 2, 2, 100501, 0, 0, 185, 100501, 2.125, "2018/09/18 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (100601, 6, "2030/12/31 15:00:00", "あかり", "【魔法】中衛で、魔法パーティの強化を担う、双子の妹。\n敵の魔法防御力を大幅に下げるスキルや、魔法攻撃力を\n上昇させ、回復効果を付与するユニオンバーストを使う。", 14, 100601, 2, 0, "アカリ", 6, 2, 100601, 0, 0, 570, 100601, 2.19, "2015/04/01 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (100701, 3, "2030/12/31 15:00:00", "みやこ", "【物理】最前衛で、ひたすら敵の攻撃を避ける幽霊少女。\nスキルで幽霊に変身することで敵の攻撃を躱し、\nユニオンバーストでは敵をプリンにして食べてしまう。", 14, 100701, 1, 0, "ミヤコ", 3, 2, 100701, 0, 0, 125, 100701, 1.7, "2015/04/01 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (100801, 7, "2030/12/31 15:00:00", "ゆき", "【魔法】後衛で物理パーティを補助する、歩く芸術作品。\n味方のユニオンバースト発動を早めるスキルのほか、\n暗闇状態にするスキルで敵の物理攻撃を封じる。", 12, 100801, 2, 0, "ユキ", 21, 2, 100801, 0, 0, 805, 100801, 2.07, "2015/04/01 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (100901, 5, "2030/12/31 15:00:00", "あんな", "【魔法】中衛から圧倒的な魔力で攻撃する、疾風の冥姫。\nユニオンバーストで敵全体に大ダメージを与えるが、\n高すぎる魔力の為、自分自身にも相応のリスクが生じる。", 11, 100901, 2, 0, "アンナ", 5, 3, 100901, 0, 0, 440, 100901, 2.25, "2015/04/01 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (101001, 7, "2030/12/31 15:00:00", "まほ", "【魔法】後衛で味方のサポートを担当するメルヘン少女。\n味方全体を強化してＴＰを回復するユニオンバーストや、\nＨＰ回復、敵を暗闇にするスキルで戦況を好転させる。", 4, 101001, 2, 0, "マホ", 7, 3, 101001, 0, 0, 795, 101001, 2.27, "2015/04/01 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (101101, 8, "2030/12/31 15:00:00", "りの", "【物理】後衛から、矢の雨を降らせる妹系アーチャー。\nクリティカル率を高める重ね掛け可能なスキルを持ち、\nダメージ回数の多いユニオンバーストをより強力にする。", 6, 101101, 1, 0, "リノ", 8, 3, 101101, 0, 0, 700, 101101, 1.97, "2015/04/01 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (101201, 7, "2030/12/31 15:00:00", "はつね", "【魔法】後衛の、対物理パーティが得意な超能力ガール。\nスキルが物理攻撃の敵に対して真価を発揮するため、\n物理攻撃型の敵パーティを一網打尽にする。", 9, 101201, 2, 0, "ハツネ", 7, 3, 101201, 0, 0, 755, 101201, 2.07, "2015/04/01 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (101301, 7, "2030/12/31 15:00:00", "ななか", "【魔法】後衛から多彩な魔法を放つ、オタク魔法少女。\n体力が一番多い相手を狙うユニオンバーストやスキルは、\n敵のＨＰ状況により攻撃対象が変わる高威力の魔法攻撃。", 9, 101301, 2, 0, "ナナカ", 7, 2, 101301, 0, 0, 740, 101301, 2.07, "2018/11/19 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (101401, 7, "2030/12/31 15:00:00", "かすみ", "【魔法】後衛で、相手の行動妨害に特化した名探偵。\n束縛や混乱を付与するスキルで相手の行動を妨害し、\n魔法防御力ダウンのフィールドを展開して王手をかける。", 9, 101401, 2, 0, "カスミ", 21, 3, 101401, 0, 0, 730, 101401, 2.27, "2019/02/28 12:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (101501, 7, "2030/12/31 15:00:00", "みさと", "【魔法】後衛で魔法キャラを支援する、みんなの先生。\nユニオンバーストのＨＰ回復＆魔防アップ、先頭キャラの\n継続ＨＰ回復スキルは、味方の耐久力を大幅に高める。", 9, 101501, 2, 0, "ミサト", 9, 2, 101501, 0, 0, 735, 101501, 2.27, "2015/04/01 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (101601, 8, "2030/12/31 15:00:00", "すずな", "【物理】後衛からクリティカル攻撃するカリスマモデル。\n必ずクリティカルするユニオンバーストのダメージは\nスキルによる攻撃力アップでさらに破壊力を増す。", 15, 101601, 1, 0, "スズナ", 8, 2, 101601, 0, 0, 705, 101601, 1.97, "2015/04/01 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (101701, 1, "2030/12/31 15:00:00", "かおり", "【物理】最前衛で、累積スキルでダメージを稼ぐ南国娘。\nスキル「精神統一」を発動すると、カオリが攻撃する度に\n敵に効果が累積し、次のダメージがどんどん増えていく。", 4, 101701, 1, 0, "カオリ", 1, 2, 101701, 0, 0, 145, 101701, 2.17, "2015/04/01 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (101801, 5, "2030/12/31 15:00:00", "いお", "【魔法】後衛で、敵全体を誘惑するセクシー先生。\n敵のＴＰを奪うスキルでユニオンバースト発動を遅らせ、\n誘惑のユニオンバーストを放ち、戦場を大混乱に陥れる。", 15, 101801, 2, 0, "イオ", 5, 3, 101801, 0, 0, 715, 101801, 2.6, "2015/04/01 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (102001, 5, "2030/12/31 15:00:00", "みみ", "【物理】中衛で、敵前衛を崩す、うさぎっこ。\nユニオンバーストは、最も近い敵に大ダメージを与えた後\n隣の敵にも攻撃するので、前衛を早期に攻め落とせる。", 13, 102001, 1, 0, "ミミ", 5, 2, 102001, 0, 0, 360, 102001, 2.125, "2015/04/01 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (102101, 3, "2030/12/31 15:00:00", "くるみ", "【物理】前衛で、味方の守りに特化した、極度の照れ屋。\nスキルで自分の周囲の物理、魔法防御力を上げつつ、\n近くの敵をスタンさせて足止めする。", 3, 102101, 1, 0, "クルミ", 3, 1, 102101, 0, 0, 197, 102101, 1.675, "2015/04/01 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (102201, 6, "2030/12/31 15:00:00", "より", "【魔法】中衛から、強力な魔法で攻め立てる、双子の姉。\n自身のＨＰと引き換えに魔法攻撃力を増幅し、\nユニオンバーストやスキルの威力を高めて攻撃する。", 14, 102201, 2, 0, "ヨリ", 6, 1, 102201, 0, 0, 575, 102201, 2.19, "2015/04/01 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (102301, 3, "2030/12/31 15:00:00", "あやね", "【物理】前衛で、戦場をかき乱す、くまっ子。\nユニオンバーストで、相手を思い切り吹き飛ばすと同時に\nスタンと大ダメージを与えることで敵陣形を大きく乱す。", 3, 102301, 1, 0, "アヤネ", 3, 2, 102301, 0, 0, 210, 102301, 1.425, "2015/04/01 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (102501, 7, "2030/12/31 15:00:00", "すずめ", "【魔法】後衛で、回復と攻撃をこなすドジっ娘メイド。\n周りの味方のＨＰを回復しつつ物理攻撃力を高める\nスキルは、中衛・後衛の攻撃役と抜群の相性。", 3, 102501, 2, 0, "スズメ", 7, 1, 102501, 0, 0, 720, 102501, 2.27, "2015/04/01 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (102601, 6, "2030/12/31 15:00:00", "りん", "【物理】中衛で物理パーティを強化するものぐさ少女。\n味方の物理攻撃力をアップしつつ、味方の魔法防御を\n高めることで攻守ともにパーティをサポートする。", 3, 102601, 1, 0, "リン", 6, 2, 102601, 0, 0, 550, 102601, 2.34, "2015/04/01 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (102701, 3, "2030/12/31 15:00:00", "えりこ", "【物理】前衛で、毒スキルで敵を粉砕する、通称壊し屋。\n最高クラスの攻撃力を持ち、ユニオンバーストで敵に\nとどめの一撃を放つ毎に、その攻撃力はさらに上昇する。", 11, 102701, 1, 0, "エリコ", 3, 2, 102701, 0, 0, 230, 102701, 1.425, "2015/04/01 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (102801, 4, "2030/12/31 15:00:00", "されん", "【物理】中衛で一発逆転を狙う、みんなのサレンママ。\nＨＰが下がるほどダメージが上昇するユニオンバーストと\n味方のＴＰを回復するスキルで、一気に形勢を逆転する。", 3, 102801, 1, 0, "サレン", 4, 3, 102801, 0, 0, 430, 102801, 2.09, "2015/04/01 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (102901, 4, "2030/12/31 15:00:00", "のぞみ", "【物理】前衛で、皆の壁になって戦うアイドルのぞみん。\n彼女がステージに立てば、味方の物理攻撃力が\n大きくアップし、さらに敵の注意を一手に惹き付ける。", 10, 102901, 1, 0, "ノゾミ", 4, 3, 102901, 0, 0, 160, 102901, 1.965, "2015/04/01 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (103001, 5, "2030/12/31 15:00:00", "にのん", "【物理】中衛で、強力な範囲攻撃を操る、忍術の使い手。\n範囲攻撃のスキルで敵を倒す事で、自分のＴＰを回復し、\n強力なユニオンバーストの発動頻度を上げる。", 12, 103001, 1, 0, "ニノン", 5, 3, 103001, 0, 0, 415, 103001, 2.25, "2015/04/01 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (103101, 5, "2030/12/31 15:00:00", "しのぶ", "【物理】中衛で、父親のドクロを召喚して戦う霊能少女。\n召喚した父親は、自分とは別に攻撃を行ってくれるほか、\nダメージを代わりに受けてくれることもある。", 14, 103101, 1, 0, "シノブ", 5, 2, 103101, 0, 0, 365, 103101, 2.25, "2015/04/01 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (103201, 5, "2030/12/31 15:00:00", "あきの", "【物理】前衛で大暴れして攻める、令嬢剣士。\n自分の周りに、味方を回復するフィールドを作り出し、\n自ら前線を支え導く姿も、名家を背負う者のあるべき姿。", 8, 103201, 1, 0, "アキノ", 5, 3, 103201, 0, 0, 180, 103201, 2.125, "2015/04/01 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (103301, 6, "2030/12/31 15:00:00", "まひる", "【物理】中衛で、相手の動きを乱す牧場主。\n敵前衛をノックバックさせることで、隊列を崩し、\n他のキャラが使う範囲攻撃の対象に敵を押し込む。", 5, 103301, 1, 0, "マヒル", 6, 2, 103301, 0, 0, 395, 103301, 2.34, "2015/04/01 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (103401, 5, "2030/12/31 15:00:00", "ゆかり", "【物理】中衛から、バリアや回復で味方を守る元聖騎士。\n傷ついた味方のＨＰやＴＰを回復するスキルを操り、\n打ち合いで消耗した所を、ピンポイントでサポートする。", 8, 103401, 1, 0, "ユカリ", 5, 1, 103401, 0, 0, 405, 103401, 2.4, "2015/04/01 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (103601, 7, "2030/12/31 15:00:00", "きょうか", "【魔法】後衛から強力な魔法で攻撃するちびっこ優等生。\nスキルで魔法攻撃力を瞬間的に高めた後に放つ\nユニオンバーストは威力抜群。", 0, 103601, 2, 0, "キョウカ", 7, 3, 103601, 0, 0, 810, 103601, 2.07, "2015/04/01 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (103701, 4, "2030/12/31 15:00:00", "とも", "【物理】前衛で、素早い斬撃を仕掛け敵を屠る剣術少女。\nユニオンバーストで自分の攻撃力と行動速度を上昇させ、\nほか攻撃スキルの殲滅能力を極限まで高め敵を圧倒する。", 2, 103701, 1, 0, "トモ", 4, 3, 103701, 0, 0, 220, 103701, 1.965, "2015/04/01 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (103801, 8, "2030/12/31 15:00:00", "しおり", "【物理】最後衛から高火力スキルを連発するスナイパー。\nダメージを与えつつ、ＴＰを回復するスキルを持ち、\n強力な一撃のユニオンバーストを、素早く発動する。", 5, 103801, 1, 0, "シオリ", 8, 2, 103801, 0, 0, 710, 103801, 1.97, "2015/04/01 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (104001, 8, "2030/12/31 15:00:00", "あおい", "【物理】最後衛から状態異常の矢を放つ、ぼっちの射手。\nダメージと共に付与する毒や麻痺の追加効果により、\n防御力の高い敵であっても、確実にＨＰを削りとる。", 9, 104001, 1, 0, "アオイ", 8, 1, 104001, 0, 0, 785, 104001, 1.97, "2015/04/01 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (104201, 7, "2030/12/31 15:00:00", "ちか", "【魔法】後衛から、前衛の戦いをサポートする唱喚士。\n自身のユニオンバーストで味方のＨＰを回復し、唱喚した\n精霊は敵への攻撃と唱喚者の魔法攻撃力強化を行う。", 10, 104201, 2, 0, "チカ", 7, 2, 104201, 0, 0, 790, 104201, 2.27, "2015/04/01 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (104301, 5, "2030/12/31 15:00:00", "まこと", "【物理】前衛で、敵の防御力を削り取る、正義の獣人。\n敵の盾役の防御力を下げ、着実にダメージを与えることで\n早期に敵の守りを突破する。", 4, 104301, 1, 0, "マコト", 5, 3, 104301, 0, 0, 165, 104301, 2.125, "2015/04/01 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (104401, 3, "2030/12/31 15:00:00", "いりや", "【魔法】中衛で命を削り攻撃する「夜を統べる者」。\n自身のＨＰと引き換えに放つスキルは高い殲滅力を誇り\n範囲攻撃における威力では他の追随を許さない。", 12, 104401, 2, 0, "イリヤ", 3, 3, 104401, 0, 0, 425, 104401, 1.425, "2015/04/01 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (104501, 2, "2030/12/31 15:00:00", "くうか", "【物理】前衛で囮となり、攻撃を引き付ける暴走ドＭ娘。\nユニオンバーストにより、自身に魔法バリアを張り、\n敵の魔法攻撃を吸収してＨＰを回復する。", 12, 104501, 1, 0, "クウカ", 2, 2, 104501, 0, 0, 130, 104501, 2.375, "2015/04/01 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (104601, 2, "2030/12/31 15:00:00", "たまき", "【物理】前衛の、対魔法パーティが得意な気まぐれ猫娘。\n攻撃スキルは、「魔法攻撃力が一番高い敵」を狙い撃ち、\nダメージ、魔法攻撃力ダウン、ＴＰ吸収と畳み掛ける。", 8, 104601, 1, 0, "タマキ", 2, 2, 104601, 0, 0, 215, 104601, 2.25, "2015/04/01 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (104701, 5, "2030/12/31 15:00:00", "じゅん", "【物理】最前衛で、完全防御スキルを操る騎士団長。\nユニオンバーストであらゆるダメージを吸収するバリアを\n展開できる。特に長期戦で圧倒的な防御性能を誇る。", 2, 104701, 1, 0, "ジュン", 5, 3, 104701, 0, 0, 135, 104701, 2.125, "2015/04/01 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (104801, 6, "2030/12/31 15:00:00", "みふゆ", "【物理】中衛の、スタンと回復のスキルを持つ傭兵戦士。\n高い防御力と自己回復能力を併せ持つ事で、\n中衛の守りを堅固にし、パーティを底支えする。", 8, 104801, 1, 0, "ミフユ", 6, 2, 104801, 0, 0, 420, 104801, 2.19, "2015/04/01 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (104901, 5, "2030/12/31 15:00:00", "しずる", "【物理】前衛で、物理攻撃から味方を守る、お姉ちゃん。\nスキルで物理無効バリアを展開し、味方全員を守るほか、\n自身はさらに物理吸収バリアを纏い、敵前衛を討つ。", 6, 104901, 1, 0, "シズル", 5, 3, 104901, 0, 0, 285, 104901, 2.375, "2015/04/01 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (105001, 7, "2030/12/31 15:00:00", "みさき", "【魔法】後衛から、範囲攻撃を行う、レディ・ウィッチ。\n複数回の範囲攻撃を放つスキルや、目の前の敵全てを\n攻撃するユニオンバーストを持ち、範囲殲滅に特化する。", 15, 105001, 2, 0, "ミサキ", 7, 1, 105001, 0, 0, 760, 105001, 2.07, "2015/04/01 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (105101, 5, "2030/12/31 15:00:00", "みつき", "【物理】中衛で、敵弱体化フィールドを操る隻眼の悪魔。\nフィールドの持続時間は短いが、範囲内の敵の\n物理防御力を大幅に減らす効果を持つ。", 11, 105101, 1, 0, "ミツキ", 5, 2, 105101, 0, 0, 565, 105101, 2.25, "2015/04/01 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (105201, 4, "2030/12/31 15:00:00", "りま", "【物理】最前衛で味方を守る、恋する乙女。\nバトル開始後、しばらくしてから最前線まで\n突進してきて、敵の目の前に立ちはだかる。", 5, 105201, 1, 0, "リマ", 4, 1, 105201, 0, 0, 105, 105201, 2.215, "2015/04/01 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (105301, 4, "2030/12/31 15:00:00", "もにか", "【物理】中衛で、味方の攻撃を鼓舞する、軍人娘。\n味方全体の物理、魔法攻撃力の大幅アップに加えて、\n攻撃速度もあげることで、戦闘の早期終結を実現する。", 12, 105301, 1, 0, "モニカ", 4, 3, 105301, 0, 0, 410, 105301, 2.24, "2015/04/01 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (105401, 1, "2030/12/31 15:00:00", "つむぎ", "【物理】前衛で、敵の妨害に特化したテーラーガール。\n敵を強制的に移動させる事で陣形を崩し、さらに\n移動速度・行動速度を低下させ相手の反撃を遅らせる。", 10, 105401, 1, 0, "ツムギ", 1, 2, 105401, 0, 0, 195, 105401, 2.42, "2015/04/01 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (105501, 48, "2030/12/31 15:00:00", "あゆみ", "【物理】中衛で、どたばたと敵をかく乱する、純情少女。\n敵をスタンさせるスキルのほか、ユニオンバーストでは\n暗闇と混乱を付与することで敵を邪魔することができる。", 12, 105501, 1, 0, "アユミ", 48, 1, 105501, 0, 0, 510, 105501, 2.34, "2019/03/19 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (105601, 4, "2030/12/31 15:00:00", "るか", "【物理】前衛で味方のため剣を振るう、いなせな姉御。\n相手へのカウンターも行う挑発や、敵の防御力を下げる\nユニオンバーストを持ち、攻防両面で実力を発揮する。", 2, 105601, 1, 0, "ルカ", 4, 3, 105601, 0, 0, 158, 105601, 1.965, "2018/11/03 19:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (105701, 4, "2030/12/31 15:00:00", "じーた", "【物理】前衛で、先手必勝の大技を繰り出す騎空士。\nスキルによるＴＰ回復は、ユニオンバーストの発動を早め\nバトルの序盤から敵前衛に大ダメージを与える。", 4, 105701, 1, 0, "ジータ", 4, 3, 170101, 0, 0, 245, 105701, 1.965, "2015/04/01 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (105801, 5, "2030/12/31 15:00:00", "ぺこりーぬ", "【物理】前衛にて、全力で仲間を護る、腹ペコ剣士。\n高いＨＰに加えて、自分自身でもＨＰ回復できるため\nギリギリまで味方の壁役を引き受ける。", 1, 105801, 1, 0, "ペコリーヌ", 5, 1, 105801, 0, 0, 155, 105801, 2.25, "2015/04/01 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (105901, 6, "2030/12/31 15:00:00", "こっころ", "【物理】中衛で、補助と攻撃で皆を支える、導きの巫女。\nユニオンバーストは、味方全体の攻撃力アップに加えて\n自らも回復するため、継続的なサポートが可能となる。", 1, 105901, 1, 0, "コッコロ", 6, 1, 105901, 0, 0, 500, 105901, 2.34, "2015/04/01 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (106001, 7, "2030/12/31 15:00:00", "きゃる", "【魔法】後衛から、強力な全体攻撃を放つ、強気な猫娘。\nスキルで敵の物理、魔法両方の防御力を下げるため\n編成を選ばずにバトルを有利に進められる。", 1, 106001, 2, 0, "キャル", 7, 1, 106001, 0, 0, 750, 106001, 2.07, "2015/04/01 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (106101, 2, "2026/08/26 11:59:59", "むいみ", "【物理】前衛で、伝説の剣「天楼覇断剣」を振るう少女。\n小技を駆使する通常の戦闘スタイルから一転、ユニオン\nバースト後は「天楼覇断剣」を携え、敵を薙ぎ払う。", 7, 106101, 1, 0, "ムイミ", 2, 3, 106101, 0, 0, 162, 106101, 1.8, "2026/08/23 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (106301, 8, "2030/12/31 15:00:00", "ありさ", "【物理】後衛の、長期戦に優れた、森の守護者見習い。\nＴＰ回復によるユニオンバーストの速攻が可能。さらに\n使用後はスキル効果が上昇するため高い殲滅力を誇る。", 1, 106301, 1, 0, "アリサ", 8, 3, 106301, 0, 0, 625, 106301, 1.97, "2015/04/01 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (106401, 4, "2030/12/31 15:00:00", "しぇふぃ", "【物理】中衛で氷雪を操り敵を凍滅する、氷竜の少女。\nユニオンバーストで獲得する【氷竜の印】を消費して、\nスキルの効果を増幅し、清廉な剣技で敵を切り伏せる。", 1, 106401, 1, 0, "シェフィ", 4, 3, 106401, 0, 0, 368, 106401, 1.84, "2021/02/15 23:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (106501, 1, "2030/12/31 15:00:00", "かや", "【物理】前衛で、敵を殴り倒す喧嘩屋ドラゴン族。\nスキルで自身の物理攻撃力を高め、全身全霊を懸け放つ\n初弾のユニオンバーストは、超大な破壊力を誇る。", 17, 106501, 1, 0, "カヤ", 1, 3, 106501, 0, 0, 168, 106501, 2.17, "2019/11/15 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (106601, 3, "2030/12/31 15:00:00", "いのり", "【物理】前衛で範囲攻撃が得意な口達者のドラゴン娘。\nユニオンバーストで範囲内の敵をまとめて吹き飛ばし、\n陣形を乱したところで、敵を一気に焼き尽くす。", 17, 106601, 1, 0, "イノリ", 3, 3, 106601, 0, 0, 197, 106601, 1.55, "2020/06/17 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (106701, 7, "2026/08/26 11:59:59", "ほまれ", "【魔法】後衛から無窮の魔力で全てを支配する龍の首領。\n障壁となる敵を龍眼で捉え、多彩な補助系スキルで敵の\n魔法攻撃からの耐性を弱め、雷霆の一撃で灰燼に帰す。", 17, 106701, 2, 0, "ホマレ", 21, 3, 106701, 0, 0, 727, 106701, 2.27, "2026/08/23 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (106801, 4, "2026/08/26 11:59:59", "らびりすた", "【物理】中衛で、万有を自在に創造する『迷宮女王』。\n七冠としての権能を解放するユニオンバーストで自身を\n極大に強化し比類ない攻撃能力で仇なす者を剿滅する。", 6, 106801, 1, 0, "ラビリスタ", 4, 3, 106801, 0, 0, 560, 106801, 1.55, "2026/08/23 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (106901, 45, "2030/12/31 15:00:00", "かいざーいんさいと", "【物理】後衛で、天の星を瞳に宿し、覇道を進む皇。\n権能を解放し敵全体のバリアと全ステータスアップ効果を\n解除し、耐久力ダウンと複数の広範囲攻撃で敵を滅する。", 1, 106901, 1, 0, "カイザーインサイト", 0, 3, 106901, 0, 0, 660, 106901, 2.0, "2022/11/15 15:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (107001, 0, "2026/08/26 11:59:59", "ねねか", "【魔法】後衛で、分身生成し敵を圧倒する『変貌大妃』。\n分身はネネカ自身と同じスキルをくり出し敵を攻撃する。\nその攻撃密度と制圧力の高さは他の追随を許さない。", 1, 107001, 2, 0, "ネネカ", 0, 3, 107001, 0, 0, 660, 107001, 2.0, "2026/08/23 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (107101, 4, "2026/08/26 11:59:59", "くりすてぃーな", "【物理】前衛で、絶対的な制圧力を誇る『誓約女君』。\n攻防一体かつ超大な破壊力を誇るユニオンバーストと、\nその発動を加速するＴＰ上昇アップスキルを併せ持つ。", 2, 107101, 1, 0, "クリスティーナ", 10, 3, 107101, 0, 0, 290, 107101, 2.0, "2026/08/23 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (107501, 5, "2026/06/30 11:59:59", "ぺこりーぬ", "【物理】前衛から強烈な範囲攻撃を放つ、渚のお姫様。\nかき氷を食べて物理攻撃力を一気に上昇させ、\nユニオンバーストを放つことで前方の敵を殲滅する。", 1, 107501, 1, 0, "ペコリーヌ（サマー）", 5, 3, 107501, 0, 0, 235, 107501, 2.125, "2026/06/22 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (107601, 6, "2030/12/31 15:00:00", "こっころ", "【物理】中衛で、物理キャラの補助を行う癒しの巫女。\nＨＰが一番少ない味方単体への特大回復スキルを持ち、\n瀕死の味方ですら瞬時に治癒する。", 1, 107601, 1, 0, "コッコロ（サマー）", 6, 1, 107601, 0, 0, 535, 107601, 2.34, "2020/06/19 15:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (107701, 7, "2026/06/30 11:59:59", "すずめ", "【魔法】後衛の防衛能力に秀でた、夏のドジっ娘メイド。\n味方全体に防御力アップと継続ＨＰ回復をかけ、\nさらに壁になるゴーレムを呼んで、戦線を支える。", 3, 107701, 2, 0, "スズメ（サマー）", 7, 3, 107701, 0, 0, 775, 107701, 2.07, "2026/06/22 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (107801, 7, "2026/06/30 11:59:59", "きゃる", "【魔法】後衛から強力な単体攻撃を放つ真夏の猫娘。\nスキルで敵の魔法防御力を下げた上で、\n敵単体への魔法攻撃を繰り出し、大ダメージを与える。", 1, 107801, 2, 0, "キャル（サマー）", 7, 3, 107801, 0, 0, 780, 107801, 1.92, "2026/06/22 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (107901, 2, "2026/06/30 11:59:59", "たまき", "【物理】前衛で連続攻撃を放つ、海辺の気まぐれ猫娘。\nランダムな相手への単体攻撃を計４度行う\nユニオンバーストは、対象がランダムだが威力は抜群。", 8, 107901, 1, 0, "タマキ（サマー）", 2, 3, 107901, 0, 0, 225, 107901, 2.0, "2026/06/22 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (108001, 6, "2030/12/31 15:00:00", "みふゆ", "【物理】中衛で、攻撃と補助の両方をこなす海の傭兵。\nユニオンバーストの効果で味方全体の物理攻撃力を高め、\n物理攻撃パーティの能力アップに一役買う。", 8, 108001, 1, 0, "ミフユ（サマー）", 6, 1, 108001, 0, 0, 495, 108001, 2.19, "2020/07/20 15:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (108101, 3, "2025/11/30 11:59:59", "しのぶ", "【物理】中衛で、迷える魂を導き救う幻夜の霊能少女。\nユニオンバーストは最も物理防御力の低い敵を狙うととも\nに、召喚された仮初の存在を一閃のもとに刈り取る。", 0, 108101, 1, 0, "シノブ（ハロウィン）", 3, 3, 108101, 0, 0, 440, 108101, 1.55, "2025/11/14 15:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (108201, 1, "2030/12/31 15:00:00", "みやこ", "【物理】中衛から、敵陣の後方を狙い撃つ幽霊狼少女。\n前方の相手を無視して妨害スキルやユニオンバーストを\n敵後方に放ち、特に防御力が低いキャラの脅威になる。", 0, 108201, 1, 0, "ミヤコ（ハロウィン）", 1, 1, 108201, 0, 0, 590, 108201, 2.42, "2020/09/23 15:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (108301, 7, "2025/11/30 11:59:59", "みさき", "【魔法】後衛で、妨害スキルを操るオシャレ魔法少女。\n相手を誘惑状態にするスキルや、複数の状態異常を\n同時に付与するユニオンバーストで相手をかく乱する。", 15, 108301, 2, 0, "ミサキ（ハロウィン）", 7, 3, 108301, 0, 0, 815, 108301, 2.07, "2025/11/14 15:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (108401, 7, "2025/12/31 11:59:59", "ちか", "【魔法】後衛で、精霊を唱喚して戦う雪華の歌姫。\nユニオンバーストで呼び出す精霊たちはＨＰやＴＰを\n回復する能力を持ち、不利な戦況をも一変させる。", 10, 108401, 2, 0, "チカ（クリスマス）", 7, 3, 108401, 0, 0, 770, 108401, 2.27, "2025/12/21 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (108501, 3, "2030/12/31 15:00:00", "くるみ", "【物理】前衛から、ベルの音色で味方を守る小さな女優。\n攻撃を受けるまで周囲にいる味方の防御力を大きく高める\nスキルを持つ。活用できれば無類の耐久力を誇る。", 15, 108501, 1, 0, "クルミ（クリスマス）", 3, 1, 108501, 0, 0, 295, 108501, 1.55, "2020/11/24 15:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (108601, 3, "2025/12/31 11:59:59", "あやね", "【物理】前衛で、敵をなぎ倒していく聖夜のくまっ子。\nユニオンバーストはＨＰを消費するが威力は絶大。\nスキルで物理攻撃力を上げ、さらにダメージアップ。", 10, 108601, 1, 0, "アヤネ（クリスマス）", 3, 3, 108601, 0, 0, 190, 108601, 1.425, "2025/12/21 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (108701, 1, "2026/01/31 11:59:59", "ひより", "【物理】前衛で、物理火力を担う、振り袖姿の元気娘。\n物理攻撃キャラの攻撃力を上昇させるスキルを使う。\nさらに高い威力の単体ユニオンバーストの攻撃力は随一。", 7, 108701, 1, 0, "ヒヨリ（ニューイヤー）", 1, 3, 108701, 0, 0, 170, 108701, 2.17, "2026/01/15 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (108801, 7, "2026/01/31 11:59:59", "ゆい", "【魔法】後衛の、補助魔法に特化した、晴れ姿の癒し手。\n自身の攻撃力と引き換えに強力なバリアと継続回復状態を\n味方全体に付与する。絶大な防御能力は他を圧倒する。", 7, 108801, 2, 0, "ユイ（ニューイヤー）", 21, 3, 108801, 0, 0, 745, 108801, 2.27, "2026/01/15 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (108901, 4, "2030/12/31 15:00:00", "れい", "【物理】前衛で、魔法攻撃から味方を守る、華麗な剣士。\nスキルで範囲内の味方に魔法無効バリアを展開し、\nさらにユニオンバーストで敵をスタンさせ攻撃を断つ。", 7, 108901, 1, 0, "レイ（ニューイヤー）", 22, 1, 108901, 0, 0, 153, 108901, 2.215, "2020/12/22 15:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (109001, 3, "2030/12/31 15:00:00", "えりこ", "【物理】前衛で、ピンチをチャンスに変える愛の壊し屋。\nスキルはＨＰを消費し、自身の攻撃力を高める。また、\nユニオンバーストはＨＰが低いほど超絶威力を発揮する。", 11, 109001, 1, 0, "エリコ（バレンタイン）", 3, 1, 109001, 0, 0, 187, 109001, 1.9, "2021/01/25 15:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (109101, 5, "2026/02/09 11:59:59", "しずる", "【物理】中衛で皆を助けるパティシエールのお姉ちゃん。\n複数のパラメータが同時に上昇するフィールドを展開し、\nさらに効果時間中はスキル効果が大幅に強化される。", 7, 109101, 1, 0, "シズル（バレンタイン）", 5, 3, 109101, 0, 0, 385, 109101, 2.125, "2026/01/31 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (109201, 7, "2030/12/31 15:00:00", "あん", "【魔法】後衛で、英霊の召喚術を武器に戦うお姫様。\n味方に英霊の加護を付与するスキルによるサポーターと、\n高威力の魔法によるアタッカーの二つの役割を併せ持つ。", 6, 109201, 2, 0, "アン", 23, 3, 109201, 0, 0, 630, 109201, 2.27, "2019/03/31 12:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (109301, 7, "2030/12/31 15:00:00", "るぅ", "【魔法】後衛で、オメメちゃんと戦う、ノーテンキ少女。\nスキルで呼び出すオメメちゃんは敵の攻撃を防ぐほか、\nその数が多いほどユニオンバーストの威力を増加させる。", 9, 109301, 2, 0, "ルゥ", 23, 1, 109301, 0, 0, 640, 109301, 2.27, "2021/03/23 15:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (109401, 1, "2030/12/31 15:00:00", "ぐれあ", "【魔法】中衛で、炎を操り敵を薙ぎ払う、竜人の少女。\n高い魔法攻撃力を生かした範囲攻撃を得意とする。\nまた、飛行能力を駆使して放つ突進攻撃も強力。", 9, 109401, 2, 0, "グレア", 1, 3, 109401, 0, 0, 525, 109401, 2.27, "2019/04/19 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (109501, 7, "2030/12/31 15:00:00", "くうか", "【魔法】最前衛で、味方を鼓舞する着物姿のドＭ娘。\n味方の魔法攻撃力を高め、敵の魔法防御力を下げる事で、\n魔法パーティのサポート兼防御役として活躍する。", 12, 109501, 2, 0, "クウカ（オーエド）", 2, 3, 109501, 0, 0, 140, 109501, 2.066, "2019/04/30 12:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (109601, 2, "2030/12/31 15:00:00", "にのん", "【物理】最前衛で、忍法を駆使して敵と戦うクノイチ。\nユニオンバーストはクリティカル時のダメージを１．５倍\nにする特性を持ち、うまくかみ合った時の威力は抜群。", 12, 109601, 1, 0, "ニノン（オーエド）", 2, 3, 109601, 0, 0, 175, 109601, 2.0, "2019/05/17 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (109701, 13, "2025/10/24 11:59:59", "れむ", "【物理】中衛で、鬼の力で敵を粉砕する、双子の妹。\n回復スキルの他にも、温度を操るスキルを得意とし、\n敵を凍結させた上でユニオンバーストで薙ぎ払う。", 9, 109701, 1, 0, "レム", 24, 3, 109701, 0, 0, 540, 109701, 2.25, "2025/10/10 12:00:00", 1, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (109801, 7, "2030/12/31 15:00:00", "らむ", "【魔法】中衛で、特殊能力で味方を補助する、双子の姉。\n相手の物理攻撃を見切って回避させる「千里眼」や、\n敵全体を束縛するユニオンバーストの補助は効果絶大。", 9, 109801, 2, 1, "ラム", 24, 1, 109801, 0, 0, 545, 109801, 2.5, "2015/04/01 15:00:00", 1, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (109901, 7, "2025/10/24 11:59:59", "えみりあ", "【魔法】後衛で、攻撃と回復をこなす、ハーフエルフ。\n高い魔力で攻撃魔法を繰り出して敵を蹴散らしつつ、\nユニオンバーストは瀕死の味方すらも瞬時に癒す。", 9, 109901, 2, 0, "エミリア", 23, 3, 109901, 0, 0, 725, 109901, 2.27, "2025/10/10 12:00:00", 1, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (110001, 8, "2026/06/30 11:59:59", "すずな", "【物理】後衛で高威力の弓技を放つ夏のカリスマモデル。\nバトル中に放つ「サマーランウェイ♪」でＴＰを全回復\nして、発動後のユニオンバーストがクリティカルになる。", 15, 110001, 1, 0, "スズナ（サマー）", 8, 3, 110001, 0, 0, 705, 110001, 1.82, "2026/06/22 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (110101, 5, "2030/12/31 15:00:00", "いお", "【魔法】後衛で、敵の体力を奪い取る、夏の夜の先生。\nダメージを与えつつ味方を回復するスキルを複数持ち、\n攻守どちらの側でも高い能力を発揮する。", 15, 110101, 2, 0, "イオ（サマー）", 5, 1, 110101, 0, 0, 715, 110101, 2.4, "2021/05/18 15:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (110201, 7, "2030/12/31 15:00:00", "みさき", "", 15, 110201, 0, 0, "ミサキ（サマー）", 7, 1, 0, 0, 0, 0, 0, 0.0, "2015/04/01 15:00:00", 0, 0, 0, 0, 0, 0);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (110301, 4, "2026/06/30 11:59:59", "されん", "【物理】中衛で、味方の速攻を支える海辺のサレンママ。\nバトル開始時に味方全体のＴＰを一気に溜めることで、\n迅速にユニオンバーストを発動させることを可能にする。", 3, 110301, 1, 0, "サレン（サマー）", 4, 3, 110301, 0, 0, 585, 110301, 2.24, "2026/06/22 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (110401, 5, "2026/07/31 11:59:59", "まこと", "【物理】前衛で攻撃対象が１つの敵に特化した海の狼娘。\n攻撃対象が１つの場合、スキルとユニオンバーストともに\n真価を発揮し他を圧倒する絶大な破壊力で敵をなぎ払う。", 4, 110401, 1, 0, "マコト（サマー）", 5, 3, 110401, 0, 0, 180, 110401, 2.125, "2026/07/15 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (110501, 1, "2030/12/31 15:00:00", "かおり", "【物理】中衛で、敵をまとめてなぎ倒す、真夏の南国娘。\n吹き飛ばし効果を持つスキルで敵をまとめ、攻撃対象が\n多い程、威力が増すユニオンバーストで敵をなぎ倒す。", 4, 110501, 1, 0, "カオリ（サマー）", 1, 1, 110501, 0, 0, 425, 110501, 2.42, "2021/06/18 15:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (110601, 7, "2026/07/31 11:59:59", "まほ", "【魔法】後衛で、膨大な魔力を振るう、真夏のおとぎ姫。\n高火力で対象がランダムなスキルやユニオンバーストは、\n攻撃対象が１つの敵に対して絶大なダメージを叩き出す。", 4, 110601, 2, 0, "マホ（サマー）", 7, 3, 110601, 0, 0, 792, 110601, 2.27, "2026/07/15 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (110701, 8, "2030/12/31 15:00:00", "あおい", "【物理】後衛で毒を操る、ぼっちエルフの編入生。\n敵が毒や猛毒になっていると強化される攻撃スキルと、\n敵の物理防御力を下げるスキルで味方をサポートする。", 4, 110701, 1, 0, "アオイ（編入生）", 8, 3, 110701, 0, 0, 680, 110701, 1.82, "2019/09/03 21:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (110801, 2, "2030/12/31 15:00:00", "くろえ", "【物理】前衛で、手数で圧倒する、ダウナー系エルフ。\n攻撃するたびに相手に【畏縮】ステータスを追加し、\nスキルのダメージと物理防御力ダウンに磨きをかける。", 2, 110801, 1, 0, "クロエ", 2, 3, 110801, 0, 0, 185, 110801, 2.125, "2019/09/16 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (110901, 1, "2030/12/31 15:00:00", "ちえる", "【物理】前衛でパンチを放つちぇる盛りＭＡＸな女の子。\nクリティカルを出すたびに【ちぇる】を溜め、自己を強化\nし続け、後半になるほど敵をちぇるっとじぇのさいする。", 2, 110901, 1, 0, "チエル", 1, 3, 110901, 0, 0, 222, 110901, 2.295, "2020/04/15 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (111001, 7, "2030/12/31 15:00:00", "ゆに", "【魔法】後衛で、味方の支援に特化した象牙の塔の才媛。\n自身の攻撃力は低いが、物理攻撃力の高い味方を強化し\n更に味方全体を魔法無効バリアで護りつつ勝利へ導く。", 2, 111001, 2, 0, "ユニ", 26, 3, 111001, 0, 0, 807, 111001, 2.27, "2020/03/31 12:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (111101, 7, "2025/11/30 11:59:59", "きょうか", "【魔法】後衛で味方の火力を高める、黒猫仮装の優等生。\n自分の魔法攻撃力に応じて効果が強化されるものと、\n効果が累積するもの等、多彩なスキルで攻撃力を高める。", 13, 111101, 2, 0, "キョウカ（ハロウィン）", 7, 3, 111101, 0, 0, 820, 111101, 2.07, "2025/11/14 15:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (111201, 1, "2030/12/31 15:00:00", "みそぎ", "【物理】前衛で範囲攻撃を放つ、カボチャ衣装の悪戯娘。敵に５カウントで爆発する爆弾を仕掛けたり、カボチャの手榴弾を投げつけたりと、様々な範囲攻撃で敵を弄ぶ。", 13, 111201, 1, 0, "ミソギ（ハロウィン）", 1, 1, 111201, 0, 0, 212, 111201, 2.17, "2021/08/16 15:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (111301, 5, "2030/12/31 15:00:00", "みみ", "【物理】中衛の、攻撃に特化した、ぐるぐるうさぎっこ。\n行動頻度は少ないが、高威力の範囲攻撃を放ち、\n味方全体の物理攻撃力を大きく高めるスキルも効果抜群。", 13, 111301, 1, 0, "ミミ（ハロウィン）", 5, 3, 111301, 0, 0, 365, 111301, 2.0, "2019/10/16 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (111401, 7, "2030/12/31 15:00:00", "るな", "【魔法】後衛で、死霊術でおともだちを作る可憐な少女。\nルナがダメージを与える度に集まってくるおともだちを、\n各スキルで消費する。消費数に応じ強大な力を発揮する。", 0, 111401, 2, 0, "ルナ", 25, 3, 111401, 0, 0, 765, 111401, 1.87, "2019/10/31 12:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (111501, 4, "2025/12/31 11:59:59", "くりすてぃーな", "【物理】前衛で戦いを愉しむ、聖夜の『誓約女君』。\nユニオンバーストを使用すると得られるコインの有無で、\n補助と攻撃の二役を切り替え、華麗に敵を斬り倒す。", 13, 111501, 1, 0, "クリスティーナ（クリスマス）", 10, 3, 111501, 0, 0, 265, 111501, 2.0, "2025/12/21 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (111601, 4, "2030/12/31 15:00:00", "のぞみ", "【物理】中衛でパーティの守りを支えるサンタアイドル。\nスキルで物理攻撃を無効化し、後方の味方が多いほど\n物理防御力を高めるユニオンバーストで生存力を高める。", 13, 111601, 1, 0, "ノゾミ（クリスマス）", 4, 1, 111601, 0, 0, 418, 111601, 2.24, "2021/10/19 15:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (111701, 3, "2030/12/31 15:00:00", "いりや", "【魔法】前衛で、血を対価に敵を攻撃する聖夜の吸血鬼。\n残りＨＰが低い程ダメージが上昇するスキルと、ＨＰを\n消費するスキルを組み合わせ、絶大な破壊力を発揮する。", 13, 111701, 2, 0, "イリヤ（クリスマス）", 3, 3, 111701, 0, 0, 255, 111701, 1.3, "2019/12/20 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (111801, 4, "2026/03/31 11:59:59", "ぺこりーぬ", "【物理】前衛で元気いっぱいに新年を祝う腹ペコお姫様。\n物理攻撃力を高めるスキルで味方を強化し、ＨＰが多い\nほどダメージが上昇するユニオンバーストで敵を討つ。", 13, 111801, 1, 0, "ペコリーヌ（ニューイヤー）", 22, 3, 111801, 0, 0, 248, 111801, 1.965, "2026/03/16 10:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (111901, 7, "2026/03/31 11:59:59", "こっころ", "【物理】前衛で、味方の補助に秀でた、新風の巫女。\n物理クリティカル時のダメージアップのスキルで味方の\n殲滅力を高めつつ、挑発や継続回復で耐久面を支える。", 1, 111901, 1, 0, "コッコロ（ニューイヤー）", 23, 3, 111901, 0, 0, 159, 111901, 1.87, "2026/03/16 10:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (112001, 7, "2026/03/31 11:59:59", "きゃる", "【魔法】後衛で、攻防双方で活躍する晴れ着姿の猫娘。\n与ダメージに応じて魔法攻撃力がアップするユニオン\nバーストで、高いベースの攻撃力がさらに強大になる。", 3, 112001, 2, 0, "キャル（ニューイヤー）", 21, 3, 112001, 0, 0, 690, 112001, 2.07, "2026/03/16 10:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (112101, 7, "2030/12/31 15:00:00", "すずめ", "【魔法】後衛で祈りによるサポートを行うドジっ娘巫女。\nスキルの魔法無効バリアで耐久力を高め、ユニオン\nバーストでＨＰ回復と行動速度アップで戦況を整える。", 1, 112101, 2, 0, "スズメ（ニューイヤー）", 21, 1, 112101, 0, 0, 722, 112101, 2.27, "2021/11/16 15:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (112201, 7, "2030/12/31 15:00:00", "かすみ", "【魔法】後衛の、妨害に特化した能力を持つ魔法探偵。\n相手のＴＰを大きく減少させるスキルや、遠くの敵を\n束縛するスキルを操り、相手の連携を大きく乱す。", 9, 112201, 2, 0, "カスミ（マジカル）", 7, 3, 112201, 0, 0, 730, 112201, 2.27, "2020/01/31 12:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (112301, 8, "2030/12/31 15:00:00", "しおり", "【物理】後衛で味方の火力の底上げを担う魔法狩人。\nユニオンバーストで味方全体の物理攻撃力を大きく高め\nスキルは範囲内の物理攻撃力を高め、輝矢の一撃を放つ。", 5, 112301, 1, 0, "シオリ（マジカル）", 8, 1, 112301, 0, 0, 712, 112301, 1.97, "2021/12/16 15:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (112401, 4, "2025/12/21 11:59:59", "うづき", "【物理】中衛で、味方を鼓舞して戦う、キュートな少女。\n味方をＴＰや攻撃力をアップさせるスキルでサポートし、\n自身も強力な範囲攻撃で敵をなぎ払う。", 18, 112401, 1, 0, "ウヅキ（デレマス）", 4, 3, 112401, 0, 0, 453, 112401, 2.24, "2025/12/10 12:00:00", 1, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (112501, 4, "2025/12/21 11:59:59", "りんでれます", "【物理】前衛で、氷を創出し味方を護る、クールな少女。\n目の前の敵を束縛するスキルや挑発で行動を妨害し、\n自身にもバリアを展開し、鉄壁の防御能力を発揮する。", 18, 112501, 1, 0, "リン（デレマス）", 4, 3, 112501, 0, 0, 153, 112501, 2.215, "2025/12/10 12:00:00", 1, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (112601, 7, "2030/12/31 15:00:00", "みお", "【魔法】後衛で攻防共に活躍するパッション溢れる少女。\nダメージを受けた味方中心に回復魔法で補助をし、\nさらに魔法攻撃を仕掛けて、敵を一網打尽にする。", 18, 112601, 2, 1, "ミオ（デレマス）", 7, 1, 112601, 0, 0, 695, 112601, 2.27, "2015/04/01 15:00:00", 1, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (112701, 6, "2030/12/31 15:00:00", "りん", "【物理】中衛から、敵の守りを貫くドングリレンジャー。\n戦闘開始と共に範囲内の敵の物理防御力を大幅に下げ、\n序盤から大ダメージを与えられる戦況を作り出す。", 3, 112701, 1, 0, "リン（レンジャー）", 6, 3, 112701, 0, 0, 422, 112701, 2.19, "2020/04/30 12:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (112801, 6, "2030/12/31 15:00:00", "まひる", "【物理】中衛で、多勢相手が十八番のまきばの戦士。\n相手を吹き飛ばすスキルを多用し敵の陣形を押し込む。\n範囲攻撃と混乱付与スキルを駆使し一気に殲滅する。", 5, 112801, 1, 0, "マヒル（レンジャー）", 6, 3, 112801, 0, 0, 390, 112801, 2.19, "2020/05/15 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (112901, 8, "2030/12/31 15:00:00", "りの", "【物理】後衛で、希望の力で戦う、不思議の国の救世主。\nクリティカルすると効果アップのスキルや味方の数が多い\n程、威力がアップするユニオンバーストで敵を殲滅する。", 6, 112901, 1, 0, "リノ（ワンダー）", 8, 3, 112901, 0, 0, 730, 112901, 1.97, "2020/06/03 19:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (113001, 6, "2030/12/31 15:00:00", "あゆみ", "【物理】中衛で、戦場の動向を自在に操る白兎の乙女。\n敵の行動速度をダウンさせ、味方の速度をアップさせる\nスキルと敵の時を止めるスキルで、常に味方を支える。", 12, 113001, 1, 0, "アユミ（ワンダー）", 6, 1, 113001, 0, 0, 508, 113001, 2.34, "2020/05/31 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (113101, 27, "2026/07/31 11:59:59", "るか", "【物理】前衛で、流麗な太刀捌きを魅せる若夏の姉御。\nダメージを与えた回数に応じて攻撃力が高まるスキルと、\n携えた二刀の幾刃もの斬撃で、眼前の敵を薙ぎ払う。", 6, 113101, 1, 0, "ルカ（サマー）", 27, 3, 113101, 0, 0, 192, 113101, 1.3, "2026/07/15 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (113201, 5, "2030/12/31 15:00:00", "あんな", "【魔法】前衛で皆の力を借り受け力を振るう真夏の冥姫。\n味方全体の魔法攻撃力を代償に自身の魔法攻撃力を劇的に\n高め、熾烈な攻撃魔法を繰り出し大ダメージを与える。", 12, 113201, 2, 0, "アンナ（サマー）", 28, 1, 113201, 0, 0, 256, 113201, 1.625, "2022/04/18 15:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (113301, 7, "2030/12/31 15:00:00", "ななか", "【魔法】中衛の多勢相手の戦いが得意な真夏の魔法少女。\n敵の数に応じて効果が上昇する防御力ダウンのスキルや、\n多彩な範囲攻撃を操り、真夏の戦いをサイカワに制する。", 12, 113301, 2, 0, "ナナカ（サマー）", 7, 3, 113301, 0, 0, 468, 113301, 2.07, "2020/07/15 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (113401, 7, "2026/07/31 11:59:59", "はつね", "【魔法】中衛から全体魔法攻撃を放つ超能力チアガール。\nユニオンバーストで敵全体に絶大な一撃を放ち、\nその後、超能力発動の反動で枕を抱えて夢の中へ。", 12, 113401, 2, 0, "ハツネ（サマー）", 29, 3, 113401, 0, 0, 567, 113401, 1.92, "2026/07/15 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (113501, 7, "2030/12/31 15:00:00", "みさと", "【魔法】後衛で、敵の脅威から生徒を守る夏女神な先生。\n味方の魔法防御力を高め、ＨＰを継続回復するスキルや、\nバリア展開のユニオンバーストで味方を堅固に守護する。", 12, 113501, 2, 0, "ミサト（サマー）", 7, 1, 113501, 0, 0, 697, 113501, 2.07, "2022/05/18 15:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (113601, 5, "2030/12/31 15:00:00", "じゅん", "【物理】前衛で、業火を従え悪を討つ真夏の騎士団長。\n敵単体にダメージを与えつつ、攻撃力を高めるユニオン\nバーストや、火傷を与えるスキルを操り敵を焼き尽くす。", 12, 113601, 1, 0, "ジュン（サマー）", 5, 3, 113601, 0, 0, 182, 113601, 2.0, "2020/08/15 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (113701, 7, "2030/12/31 15:00:00", "あかり", "【魔法】中衛で、魔法攻撃をお見舞いする双子の妹天使。\n効果時間が短い分、絶大な効果の強化魔法で自身の攻撃力\nを大きく高め、威力抜群の単体魔法で敵を一掃する。", 12, 113701, 2, 0, "アカリ（エンジェル）", 7, 3, 113701, 0, 0, 530, 113701, 1.92, "2020/09/03 19:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (113801, 6, "2030/12/31 15:00:00", "より", "【魔法】中衛で、補助魔法で味方を助ける双子の姉天使。\n防御力を大幅に高めつつ、対象の味方に敵の注意を引か\nせるなど、特殊で強力なスキルを駆使し敵を翻弄する。", 12, 113801, 2, 0, "ヨリ（エンジェル）", 6, 3, 113801, 0, 0, 531, 113801, 2.34, "2020/09/19 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (113901, 2, "2025/10/31 11:59:59", "つむぎ", "【物理】前衛で敵の物理攻撃を妨害する吸血鬼テーラー。\n挑発と物理無効バリア、さらに最も物理攻撃力が高い敵を\n狙った妨害スキルによって、鉄壁の防御を織り上げる。", 12, 113901, 1, 0, "ツムギ（ハロウィン）", 2, 3, 113901, 0, 0, 152, 113901, 2.375, "2025/10/24 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (114001, 4, "2030/12/31 15:00:00", "れい", "【物理】中衛で、手負いの敵を死に誘う、幽雅の剣士。\nＨＰが50％未満の敵に対し放つと、威力が大アップする\n範囲攻撃を繰り出し負傷した敵の戦意を一気に叩き折る。", 12, 114001, 1, 0, "レイ（ハロウィン）", 4, 3, 114001, 0, 0, 375, 114001, 1.965, "2020/10/15 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (114101, 1, "2030/12/31 15:00:00", "まつり", "【物理】前衛で鋭爪を突き立てるハロウィン騎士見習い。\nユニオンバーストの使用回数に応じて強化されるスキルで\n与えるダメージと行動速度をアップさせ、敵を斬り裂く。", 12, 114101, 1, 0, "マツリ（ハロウィン）", 1, 1, 114101, 0, 0, 186, 114101, 2.295, "2022/07/19 8:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (114201, 4, "2030/12/31 15:00:00", "もにか", "【物理】中衛で愛と希望の力を胸に指揮を執る魔法提督。\nユニオンバーストで敵単体の物理防御力を下げ、範囲内の\n味方の物理攻撃力アップスキルで、一気に戦況を決める。", 12, 114201, 1, 0, "モニカ（マジカル）", 4, 3, 114201, 0, 0, 528, 114201, 2.24, "2020/10/31 12:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (114301, 4, "2030/12/31 15:00:00", "とも", "【物理】中衛で正義の力を魔法にのせて戦う魔法剣士。\n自身の物理攻撃力を魔法攻撃力に加える魔法少女の力と、\nたゆまぬ努力で獲得した剣技で、華麗な魔法攻撃を放つ。", 2, 114301, 1, 0, "トモ（マジカル）", 4, 3, 114301, 0, 0, 402, 114301, 2.0, "2020/11/21 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (114401, 5, "2025/12/31 11:59:59", "あきの", "【物理】前衛で味方のサポートを力に戦う、聖夜の令嬢。\nステータスアップ効果を受けると増加する【聖夜の煌き】\nでスキルを大きく強化し、聖夜を彩る強烈な一撃を放つ。", 2, 114401, 1, 0, "アキノ（クリスマス）", 5, 3, 114401, 0, 0, 189, 114401, 2.0, "2025/12/21 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (114501, 4, "2030/12/31 15:00:00", "されん", "【物理】前衛で、光を操り味方を守る聖夜のサレンママ。\n敵の攻撃を防ぎ、ダメージを与えるユニオンバーストや、\nダメージを与えつつ回復するスキルで、攻守双方を担う。", 3, 114501, 1, 0, "サレン（クリスマス）", 4, 3, 114501, 0, 0, 150, 114501, 2.09, "2020/12/21 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (114601, 5, "2030/12/31 15:00:00", "ゆかり", "【物理】中衛で物理キャラを支援し戦う聖夜の元聖騎士。\n魔法攻撃力の高い敵単体のＴＰ減少や周囲の味方の魔法\n防御力アップスキルで、対魔法戦で無類の輝きを放つ。", 2, 114601, 1, 0, "ユカリ（クリスマス）", 5, 1, 114601, 0, 0, 408, 114601, 2.09, "2022/09/17 15:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (114701, 2, "2030/12/31 15:00:00", "むいみ", "【物理】前衛で、新風纏う「天楼覇断剣」を振るう少女。\n皆より一足遅れて突撃し、敵の前衛を吹き飛ばした後、\n強化した範囲物理攻撃で、ダンゴになった敵を斬り払う。", 2, 114701, 1, 0, "ムイミ（ニューイヤー）", 31, 1, 114701, 0, 0, 138, 114701, 2.0, "2022/10/16 15:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (115001, 7, "2026/01/31 11:59:59", "ねねか", "【魔法】中衛で艶やかな晴れ着を身に纏う『変貌大妃』。\n味方の魔法攻撃力アップやＨＰ、ＴＰを回復させるスキル\nで攻守にわたってサポートし苛烈な戦況でも勝利に導く。", 2, 115001, 2, 0, "ネネカ（ニューイヤー）", 21, 3, 115001, 0, 0, 562, 115001, 2.07, "2026/01/15 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (115501, 2, "2026/07/31 11:59:59", "こっころ", "【物理】中衛で、尊き儀装束を纏うエルフの里の巫女。\n自分の攻撃力を強化し、さらにＴＰ回復で攻撃の手数を\n増やす。クリティカル時の猛攻で仲間を守る剣となる。", 1, 115501, 1, 0, "コッコロ（儀装束）", 2, 3, 115501, 0, 0, 533, 115501, 2.0, "2026/07/15 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (115601, 7, "2030/12/31 15:00:00", "ゆい", "【魔法】中衛で精霊術を操り味方を支える儀装の魔法士。\n複数の物理攻撃力の強化スキルで味方を攻撃支援しつつ\n強力な回復スキルで、前線を整えバトルを掌握する。", 7, 115601, 2, 0, "ユイ（儀装束）", 7, 1, 115601, 0, 0, 578, 115601, 1.97, "2022/11/17 15:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (115701, 7, "2030/12/31 15:00:00", "かすみ", "【魔法】後衛で、敵の防御力を削ぎ取る渚の名探偵。\n攻撃力が高い敵に目標を定めて防御力を下げつつ、\n味方を強化するスキルで、どんな難事件も解決へと導く。", 9, 115701, 2, 0, "カスミ（サマー）", 7, 3, 115701, 0, 0, 738, 115701, 2.27, "2021/02/23 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (115801, 4, "2030/12/31 15:00:00", "りま", "【物理】前衛の魔法の果実でお姫様姿になった恋乙女。\n獣の姿からユニオンバーストで一定時間、人の姿に変身し\n味方全体の攻撃力アップスキルで、火力の底上げをする。", 5, 115801, 1, 0, "リマ（シンデレラ）", 4, 1, 115801, 0, 0, 173, 115801, 2.27, "2022/12/19 15:00:00", 0, 0, 0, 116101, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (115901, 5, "2030/12/31 15:00:00", "まこと", "【物理】前衛で、華装に身を包み流麗な剣舞を舞う狼娘。\n周囲の味方の数に応じて、スキルの威力と物理攻撃力\nアップのスキル効果が上がり、鼓舞激励の一斬を振るう。", 4, 115901, 1, 0, "マコト（シンデレラ）", 5, 3, 115901, 0, 0, 166, 115901, 2.27, "2021/03/03 19:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (116001, 7, "2030/12/31 15:00:00", "まほ", "【魔法】後衛から、優雅に味方を支援するマホ先生。\n物理攻撃をする味方の攻撃力アップや、ＴＰを回復するス\nキルで、しゃなりしゃなりと戦況を変える。", 9, 116001, 2, 0, "マホ（シンデレラ）", 7, 3, 116001, 0, 0, 645, 116001, 2.27, "2021/03/22 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (116201, 2, "2030/12/31 15:00:00", "くろえ", "【物理】前衛で疾風の如く駆け抜ける、ダウナー女子。\n特定回数ダメージを与えるたびＴＰを全回復するスキルと\n発動ごとに攻撃力アップのスキルで勝利のテープを掴む。", 2, 116201, 1, 0, "クロエ（聖学祭）", 2, 3, 116201, 0, 0, 184, 116201, 2.125, "2021/04/15 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (116301, 1, "2030/12/31 15:00:00", "ちえる", "【物理】前衛で聖学祭を盛りアゲる、はぴちぇる系女子。\n攻撃ヒットのたびに【ちぇる】を貯め、威力が増すスキル\nと味方全体の物理攻撃力アップ効果のＵＢで勝利に導く。", 2, 116301, 1, 0, "チエル（聖学祭）", 32, 3, 116301, 0, 0, 223, 116301, 2.295, "2021/03/31 12:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (116401, 7, "2030/12/31 15:00:00", "ゆに", "【魔法】後衛から、仲間を啓蒙するユニちゃんズの才媛。\n自分以外の味方全員の物理・魔法両方の攻撃力アップと\nクリティカル時のダメージアップで皆を勝利へと導く。", 2, 116401, 2, 0, "ユニ（聖学祭）", 39, 3, 116401, 0, 0, 808, 116401, 2.27, "2022/02/08 12:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (116501, 3, "2030/12/31 15:00:00", "いのり", "【物理】前衛で威勢よく、まくしたてる口撃系ドラゴン。\n全体物理攻撃力アップのＵＢは、味方の防御力を下げる\n代わりにＨＰが多いほど効果を高め、味方を勝利に導く。", 17, 116501, 1, 0, "イノリ（タイムトラベル）", 3, 3, 116501, 0, 0, 252, 116501, 2.295, "2021/04/30 12:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (116601, 1, "2030/12/31 15:00:00", "かや", "【物理】前衛で味方を勝利にナビする喧嘩屋ドラゴン族。\nユニオンバーストで自身の攻撃速度を極大アップさせ、\n物理攻撃力アップスキルのシナジーで拳の雨を降らせる。", 17, 116601, 1, 0, "カヤ（タイムトラベル）", 1, 3, 116601, 0, 0, 169, 116601, 2.295, "2021/05/21 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (116701, 33, "2030/12/31 15:00:00", "あおい", "【物理】中衛で敵を妨害する、作業服姿のぼっちエルフ。\n友情の絆で結ばれた『マイフレンドくん』と放つＵＢは、\n敵の動きを阻み、物理防御力を劇的に下げる。", 9, 116701, 1, 0, "アオイ（作業服）", 33, 3, 116701, 0, 0, 527, 116701, 1.82, "2021/05/31 12:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (116801, 2, "2030/12/31 15:00:00", "たまき", "【物理】前衛でたい焼き器片手に悪を討つ売り子の猫娘。\n味方全体を物理攻撃力アップとＴＰ回復させ、ＵＢでさら\nに自分の攻撃力を特大強化し、驚異の威力を発揮する。", 8, 116801, 1, 0, "タマキ（作業服）", 2, 1, 116801, 0, 0, 216, 116801, 2.295, "2023/03/16 15:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (116901, 6, "2030/12/31 15:00:00", "みふゆ", "【物理】前衛で、皆の盾となり進攻するバイトリーダー。\nバトル序盤は物理の攻防両方をスキルで強化。ＵＢ発動毎\nに自分のクリティカルをアップし猛烈な攻撃を繰り出す。", 8, 116901, 1, 0, "ミフユ（作業服）", 6, 3, 116901, 0, 0, 275, 116901, 2.065, "2021/06/16 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (117001, 3, "2026/08/31 11:59:59", "えりこ", "【物理】中衛で、火花を纏い夕闇を彩る真夏の壊し屋。\n二つのスキルで物理防御力を下げ、ダメージ量に応じて\nクリティカル上昇が延長するＵＢで眼前の敵を粉砕する。", 11, 117001, 1, 0, "エリコ（サマー）", 3, 3, 117001, 0, 0, 407, 117001, 1.55, "2026/08/26 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (117101, 5, "2030/12/31 15:00:00", "しずる", "【物理】前衛で、堅牢に仲間を守る海辺のお姉ちゃん。\n物理防御力が高い程、効果が高まる複数のスキルを巧みに\n操り防御と補助役をしつつ範囲攻撃で攻撃役をもこなす。", 6, 117101, 1, 0, "シズル（サマー）", 5, 3, 117101, 0, 0, 163, 117101, 2.0, "2021/07/15 12:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (117201, 4, "2026/09/30 11:59:59", "のぞみ", "【物理】中衛でみんなを応援する真夏のトップアイドル。\nすべてのスキルで味方全体の物理攻撃をサポートし、\nバトル中盤から味方全体のＴＰ回復で、皆を勝利に導く。", 10, 117201, 1, 0, "ノゾミ（サマー）", 4, 3, 117201, 0, 0, 417, 117201, 2.09, "2026/09/22 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (117301, 7, "2030/12/31 15:00:00", "ちか", "【魔法】中衛で、守護の賛歌を捧げる夏海の歌姫。\n最序盤に味方の魔法防御を大幅に強化し、吸収バリアや\nＨＰ回復スキルで、如何なる猛攻からも味方を守る。", 10, 117301, 2, 0, "チカ（サマー）", 7, 3, 117301, 0, 0, 520, 117301, 2.07, "2021/08/15 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (117401, 1, "2030/12/31 15:00:00", "つむぎ", "【物理】中衛で敵を引き寄せ陣形を崩す夕凪のテーラー。\n最も攻撃力の高い敵を、敵陣から自陣に引き寄せつつ\n束縛や行動速度ダウンを絡めたスキルで敵の自由を縛る。", 10, 117401, 1, 0, "ツムギ（サマー）", 1, 1, 117401, 0, 0, 355, 117401, 2.42, "2023/05/16 15:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (117501, 5, "2030/12/31 15:00:00", "みつき", "【物理】中衛で、戦況のすべてを見据える隻眼の闇医者。\nＨＰが低い敵を束縛し防御力ダウンスキルで仕掛けつつ\n呪詛の毎秒増加する継続ダメージで敵の命を刻々と蝕む。", 11, 117501, 1, 0, "ミツキ（オーエド）", 5, 3, 117501, 0, 0, 552, 117501, 2.4, "2021/09/03 19:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (117601, 7, "2030/12/31 15:00:00", "ゆき", "【魔法】後衛で、迷える皆を救う白衣を纏いし美の象徴。\n一番低い味方１キャラのＴＰを回復し、ＨＰ回復スキルで\n守り、魔法攻撃力アップのスキルで一気に攻め落とす。", 12, 117601, 2, 0, "ユキ（オーエド）", 7, 3, 117601, 0, 0, 798, 117601, 2.0, "2021/09/13 12:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (117701, 1, "2025/11/30 11:59:59", "かおり", "【物理】前衛の敵を追い詰める程、力を増す幽玄南国娘。\n敵の体力が少ない程、効果が高まる攻撃力アップスキルと\nダメージ量アップの攻撃スキルで、敵を逃さず仕留める。", 4, 117701, 1, 0, "カオリ（ハロウィン）", 1, 3, 117701, 0, 0, 156, 117701, 2.17, "2025/11/14 15:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (117801, 36, "2030/12/31 15:00:00", "にのん", "【物理】中衛で物理攻撃タイプの味方を強化するシノビ。\n味方の物理攻撃力アップや行動速度アップのスキル効果で\n味方全体の攻撃力を底上げし、勝利の笛を吹きならす。", 12, 117801, 1, 0, "ニノン（ハロウィン）", 36, 1, 117801, 0, 0, 518, 117801, 2.25, "2023/07/18 15:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (117901, 8, "2030/12/31 15:00:00", "すずな", "【物理】後衛でアタッカーを狙う小悪魔カリスマモデル。\n誘惑状態だと威力アップの攻撃スキルや、ＴＰを奪い取る\n妨害スキルを放ち、物理攻撃力が最も高い敵を狙い撃つ。", 15, 117901, 1, 0, "スズナ（ハロウィン）", 8, 3, 117901, 0, 0, 761, 117901, 1.97, "2021/10/15 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (118001, 35, "2026/09/30 11:59:59", "くれじった", "【物理】後衛で、攻撃と敵の弱体化の二役で輝く女商人。\n生ける金貨が詰まった財布を投げつける不意打ちや、\n金貨の嵐を巻き起こす攻撃で、相手の防御を大きく崩す。", 0, 118001, 1, 0, "クレジッタ", 35, 3, 118001, 0, 0, 751, 118001, 1.97, "2026/09/22 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (118101, 7, "2026/08/26 11:59:59", "らんふぁ", "【魔法】後衛で、美しい旋律を紡ぎ支援する幽寂の歌姫。\n味方の強化と敵の弱体化の両方面での補助を行い、さらに\n召喚した鉱石の飛竜との波状攻撃により敵を鎮圧する。", 19, 118101, 2, 0, "ランファ", 21, 3, 118101, 0, 0, 782, 118101, 2.07, "2026/08/23 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (118201, 0, "2026/08/26 11:59:59", "みそら", "【魔法】後衛で笑顔とともに破壊を振りまく溌溂少女★\n最大３体に着弾するスキルとＵＢは【PSI★チャージ】\n状態で魔防ダウン効果を追加し、邪魔者たちを殲滅する。", 19, 118201, 2, 0, "ミソラ", 0, 3, 118201, 0, 0, 730, 118201, 1.7, "2026/08/23 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (118301, 0, "2030/12/31 15:00:00", "はつね", "", 0, 118301, 0, 1, "ハツネ（ハツネ&シオリ）", 0, 3, 0, 0, 0, 732, 0, 0.0, "2015/04/01 15:00:00", 0, 180701, 0, 0, 1, 0);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (118401, 0, "2030/12/31 15:00:00", "しおり", "", 0, 118401, 0, 1, "シオリ（ハツネ&シオリ）", 0, 3, 0, 0, 0, 732, 0, 0.0, "2015/04/01 15:00:00", 0, 180701, 0, 0, 1, 0);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (118501, 37, "2030/12/31 15:00:00", "かりん", "【魔法】後衛で皆を支える、ギルド管理協会の職員さん。\n通常攻撃の代わりに味方の能力を高める魔法を掛け、\n味方の守護や敵への妨害など、完璧なサポートをこなす。", 0, 118501, 2, 0, "カリン", 37, 1, 118501, 0, 0, 787, 118501, 2.0, "2021/10/19 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (118601, 0, "2030/12/31 15:00:00", "ねびあ", "【魔法】後衛を飛び出し悪戯の限りを尽くす幻惑の妖精。\n敵陣を勝手気ままに飛び回り、敵の攻撃を空振りさせて、\nＵＢで４種の妨害効果をランダムに与え大混乱に陥れる。", 0, 118601, 2, 0, "ネビア", 0, 3, 118601, 0, 0, 826, 118601, 2.0, "2024/08/10 21:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (119001, 7, "2030/12/31 15:00:00", "いお", "【魔法】後衛で魔法アタッカーを妨害する闇のせんせー。\n最も魔法攻撃力が高い敵を、誘惑とＴＰダウンで妨害し\nＴＰ回復スキルで味方を援護することで戦況を支配する。", 15, 119001, 2, 0, "イオ（ノワール）", 7, 3, 119001, 0, 0, 714, 119001, 2.27, "2021/11/03 19:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (119101, 7, "2030/12/31 15:00:00", "くうか", "【魔法】前衛で、猛攻をバリアで受けきる闇のドＭ娘。\n最も魔法攻撃力が高い味方の魔法攻撃力とクリティカルを\nアップさせ、魔法防御力ダウンスキルで敵を怯ませる。", 12, 119101, 2, 0, "クウカ（ノワール）", 26, 3, 119101, 0, 0, 143, 119101, 2.545, "2021/11/16 12:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (119201, 6, "2030/12/31 15:00:00", "まひる", "【物理】中衛で味方を支援し、守護する聖夜の牧場主。\n範囲内の敵をノックバックさせることで相手の隊列を崩し\n全体物理バリア展開と単体ＨＰ回復で激戦を勝利に導く。", 5, 119201, 1, 0, "マヒル（クリスマス）", 6, 1, 119201, 0, 0, 397, 119201, 2.19, "2023/09/19 15:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (119301, 8, "2030/12/31 15:00:00", "りの", "【物理】後衛で、攻撃と支援を担う聖夜のアーチャー。\n物理攻撃力と物理クリティカルアップスキルで周囲を強化\nし、クリティカルで威力が増大するＵＢで敵を粉砕する。", 6, 119301, 1, 0, "リノ（クリスマス）", 8, 3, 119301, 0, 0, 762, 119301, 1.97, "2021/12/22 12:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (119401, 5, "2030/12/31 15:00:00", "ぺこりーぬ", "", 0, 119401, 0, 0, "ペコリーヌ", 0, 1, 0, 0, 0, 0, 0, 0.0, "2022/01/31 12:00:00", 0, 0, 0, 0, 0, 0);
