INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (119901, 1, "2025/12/31 11:59:59", "みやこ", "【物理】中衛で、味方をプリンで強化する幽霊聖少女。\n物理攻撃力と物理クリティカルアップのプリンパワーの\nフィールドで自分のスキルも強化し、猛攻を繰り出す。", 14, 119901, 1, 0, "ミヤコ（クリスマス）", 1, 3, 119901, 0, 0, 302, 119901, 2.17, "2025/12/21 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (120001, 5, "2026/03/31 11:59:59", "しずる", "【物理】前衛で猛攻から味方を守護する闇のお姉ちゃん。\nバトル開始時の行動不能無効スキルで周囲の味方を守り、\n範囲を束縛するスキルで敵を牽制し、戦況を一変する。", 6, 120001, 1, 0, "シズル（ノワール）", 5, 3, 120001, 0, 0, 190, 120001, 2.375, "2026/03/16 10:00:00", 0, 0, 0, 0, 1, 450);
