INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (120701, 4, "2026/01/31 11:59:59", "しぇふぃ", "【物理】前衛で、雪花舞う晴れ空をゆく新春氷竜少女。\nＵＢで顕現させる氷竜の牙で味方への強化スキルを高め\n自身の範囲攻撃技と共に苛烈な攻勢で敵陣を凍滅する。", 1, 120701, 1, 0, "シェフィ（ニューイヤー）", 22, 3, 120701, 0, 0, 283, 120701, 1.84, "2026/01/15 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (120801, 4, "2030/12/31 15:00:00", "るか", "【物理】前衛で雪月花の舞を納める新春の姉御。\n攻撃を当てる度に増加する【剣の刻印】でＵＢとスキルの\n威力を上昇させ、目にも止まらぬ斬撃で敵を圧倒する。", 2, 120801, 1, 0, "ルカ（ニューイヤー）", 22, 1, 120801, 0, 0, 193, 120801, 1.3, "2023/10/16 15:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (120901, 3, "2026/01/31 11:59:59", "いりや", "【魔法】中衛で自らの血を代償に力を振るう新春吸血鬼。\n自身のＨＰを消費して放つ強力なスキルと、敵からＴＰを\n吸収するスキルを自在に操り、目の前の敵を撃滅する。", 12, 120901, 2, 0, "イリヤ（ニューイヤー）", 38, 3, 120901, 0, 0, 424, 120901, 1.425, "2026/01/15 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (121001, 5, "2026/02/09 11:59:59", "ぺこりーぬ", "【物理】前衛で、仲間との絆を力に変え戦う腹ペコ王女。\n敵のＨＰ状態で永続の物理攻撃力上昇と、短時間の特大\n攻撃力上昇＆自己ＴＰ回復を使い分け戦況を一変させる。", 1, 121001, 1, 0, "ペコリーヌ（オーバーロード）", 41, 3, 121001, 0, 0, 164, 121001, 2.25, "2026/01/31 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (121101, 7, "2026/02/09 11:59:59", "きゃる", "【魔法】中衛で仲間との絆を力に変え戦うツンデレ猫娘。\n敵を妨害するスキルと、ＵＢで敵全体を恐慌状態にし既に\n恐慌状態の敵のＴＰをダウンさせ、全戦場を掌握する。", 1, 121101, 2, 0, "キャル（オーバーロード）", 42, 3, 121101, 0, 0, 588, 121101, 2.07, "2026/01/31 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (121201, 4, "2030/12/31 15:00:00", "らびりすた", "【物理】前衛で世界の理をすべて見つめる『迷宮女王』。\n味方を攻撃面で強化し、継続ＨＰ回復を全体に付与する\nスキルで戦線を整え、自身も圧倒的な力で敵を殲滅する。", 6, 121201, 1, 0, "ラビリスタ（オーバーロード）", 40, 1, 121201, 0, 0, 260, 121201, 1.55, "2023/11/16 15:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (121301, 3, "2030/12/31 15:00:00", "くるみ", "【物理】後衛で、皆のため意を決し奮起する小さな女優。\n残りＨＰが多いほど物理攻撃力がアップし、物理攻撃無効\nバリアのスキルやＨＰ・ＴＰ継続回復で味方を支援する。", 3, 121301, 1, 0, "クルミ（ステージ）", 3, 3, 121301, 0, 0, 731, 121301, 1.9, "2022/03/03 19:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (121401, 7, "2030/12/31 15:00:00", "みさき", "【魔法】後衛で後ろの味方を強化する魔法少女の看板娘。\n後衛の味方をバリアとＴＰ継続回復で支援し、自分の魔法\n攻撃力に応じ強化される攻撃力アップスキルで鼓舞する。", 15, 121401, 2, 0, "ミサキ（ステージ）", 7, 3, 121401, 0, 0, 742, 121401, 2.27, "2022/03/15 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (121501, 6, "2026/04/15 11:59:59", "あゆみ", "【物理】中衛で、闇夜に身を潜める神出鬼没の怪盗少女。\n敵の目の前から姿を消す隠密スキルや、遠くの敵に対する\nＴＰダウンスキルを駆使して、敵陣後方から瓦解させる。", 12, 121501, 1, 0, "アユミ（怪盗）", 6, 3, 121501, 0, 0, 590, 121501, 2.0, "2026/03/31 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (121601, 3, "2030/12/31 15:00:00", "いのり", "【物理】前衛で闇に紛れ会心の一撃を放つ怪盗ドラゴン。\n隠密効果中、ダメージが大アップし必ずクリティカルする\nＵＢとスキルを駆使し安定したダメージを敵に叩き込む。", 17, 121601, 1, 0, "イノリ（怪盗）", 3, 3, 121601, 0, 0, 292, 121601, 1.425, "2022/04/15 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (121701, 0, "2030/12/31 15:00:00", "あきの", "", 0, 121701, 0, 1, "アキノ（アキノ＆サレン）", 0, 3, 0, 0, 0, 421, 0, 0.0, "2015/04/01 15:00:00", 0, 180901, 0, 0, 1, 0);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (121801, 0, "2030/12/31 15:00:00", "されん", "", 0, 121801, 0, 1, "サレン（アキノ＆サレン）", 0, 3, 0, 0, 0, 421, 0, 0.0, "2015/04/01 15:00:00", 0, 180901, 0, 0, 1, 0);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (121901, 5, "2030/12/31 15:00:00", "あんな", "【魔法】前衛で己を鼓舞し高めた魔力を放つ蒼海の冥姫。\n発動の度、攻撃力とクリティカル時ダメージが上昇する\nＵＢと自己犠牲を払う強力な範囲攻撃技で敵を撃滅する。", 12, 121901, 2, 0, "アンナ（パイレーツ）", 5, 3, 121901, 0, 0, 293, 121901, 2.125, "2022/05/15 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (122001, 3, "2030/12/31 15:00:00", "しのぶ", "【物理】中衛で、彷徨える魂を解き放つ海星の霊能少女。\n攻撃の際、付与する【霊錨の刻印】を駆使し、ダメージ量\nアップのスキルと防御力ダウンのＵＢで敵を浄滅へ導く。", 14, 122001, 1, 0, "シノブ（パイレーツ）", 3, 3, 122001, 0, 0, 380, 122001, 1.425, "2022/05/03 19:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (122101, 35, "2030/12/31 15:00:00", "あおい", "【物理】後衛で百千の矢を放つ、ぼっちの山籠りエルフ。\n物理魔法無効バリアで耐え凌ぎ、敵全体への射撃と自分の\n間合いに入った敵への強力な弓雨の追撃で掃討する。", 9, 122101, 1, 0, "アオイ（キャンプ）", 35, 1, 122101, 0, 0, 731, 122101, 1.97, "2024/04/18 15:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (122201, 4, "2030/12/31 15:00:00", "ゆかり", "【物理】中衛で最高の一杯を自然と共に愉しむ元聖騎士。\n【至福のひと時】が増えるほどに、味方の物理攻撃力や\nクリティカル時のダメージを強力に強化し、勝利を掴む。", 8, 122201, 1, 0, "ユカリ（キャンプ）", 4, 3, 122201, 0, 0, 419, 122201, 1.84, "2022/05/31 12:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (122301, 43, "2030/12/31 15:00:00", "うぁんぴぃ", "【魔法】中衛で、幼き竜と共に歩むさいきょーの吸血姫。\n味方全体の強化と、敵のＴＰを吸収するスキルで力を蓄え\nＵＢ発動後ベスと共闘し防御ダウンと強撃で攻勢に出る。", 0, 122301, 2, 0, "ヴァンピィ", 43, 3, 122301, 0, 0, 564, 122301, 1.425, "2022/06/15 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (122401, 1, "2030/12/31 15:00:00", "ひより", "【物理】前衛で皆にエールを送り鼓舞する真夏の元気娘。\n味方のＨＰを継続回復し行動速度アップの他、味方の数に\n応じてクリティカル強化と攻撃力を引き上げ勝利に導く。", 8, 122401, 1, 0, "ヒヨリ（サマー）", 1, 1, 122401, 0, 0, 264, 122401, 2.42, "2024/06/17 15:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (122501, 4, "2026/08/31 11:59:59", "れい", "【物理】前衛で水刃の加護を纏い水面を駆ける渚の剣士。\nクリティカル時のダメージを底上げしＵＢ発動の度、纏う\n【水刃の加護】で全スキルダメージを上げ、敵陣を穿つ。", 0, 122501, 1, 0, "レイ（サマー）", 4, 3, 122501, 0, 0, 250, 122501, 1.965, "2026/08/26 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (122601, 7, "2030/12/31 15:00:00", "ゆい", "【魔法】中衛で、魔法キャラを補助する夜凪の魔法士。\n累積する攻撃強化スキルとＴＰ回復、物魔両面の無効\nバリアや継続ＨＰ回復で攻守共に味方を支え勝利へ導く。", 0, 122601, 2, 0, "ユイ（サマー）", 7, 3, 122601, 0, 0, 554, 122601, 2.27, "2022/07/15 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (122701, 7, "2030/12/31 15:00:00", "きょうか", "【魔法】後衛で、難しい魔法の練習に励む海辺の優等生。\nランダムな敵に当たるスキルの威力は攻撃の際に付与する\n【バタフライシール】で増幅し、防御力もダウンさせる。", 0, 122701, 2, 0, "キョウカ（サマー）", 7, 3, 122701, 0, 0, 812, 122701, 1.92, "2022/08/15 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (122801, 1, "2030/12/31 15:00:00", "みそぎ", "【物理】前衛で敵後方に花火を仕掛ける夜涼みの悪戯娘。\n敵の最前衛をスタンで足止めしつつ、最後衛を中心とした\nＵＢで狭範囲の敵を引き寄せ、ＴＰダウンで攻勢を阻む。", 0, 122801, 1, 0, "ミソギ（サマー）", 1, 1, 122801, 0, 0, 237, 122801, 2.295, "2024/07/16 15:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (122901, 5, "2026/08/31 11:59:59", "みみ", "【物理】中衛で巨大バルーンと跳ね回る夏色うさぎっこ。\nＵＢやスキルで全てのマルチターゲットに追加ダメージを\n与え、自己強化と防御力ダウンで強敵のブレイクを狙う。", 0, 122901, 1, 0, "ミミ（サマー）", 5, 3, 122901, 0, 0, 361, 122901, 2.25, "2026/08/26 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (123001, 44, "2026/08/26 11:59:59", "あめす", "【魔法】後衛で、新たな姿で騎士の冒険を支える妖精。\nダメージカットや防御力アップ、無効バリアで味方を護り\nバリアを起点とする攻撃力とＴＰの支援で攻勢に転ずる。", 0, 123001, 2, 0, "アメス", 44, 3, 123001, 0, 0, 746, 123001, 2.27, "2026/08/23 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (123101, 7, "2030/12/31 15:00:00", "まほ", "【魔法】後衛でぬいぐるみ達と大冒険に挑むマホ隊員。\n味方に付与する【ふわふわウール】は被ダメージ時に消費\nされＴＰを回復し、一気呵成の反撃で活路を切り拓く。", 0, 123101, 2, 0, "マホ（エクスプローラー）", 7, 3, 123101, 0, 0, 793, 123101, 1.795, "2022/09/03 19:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (123201, 3, "2030/12/31 15:00:00", "あやね", "【物理】前衛で、相棒と困難を越え猛進するアヤネ隊員。\n群る敵を二つの範囲攻撃で一気に捉え、周囲の味方の物理\n攻撃力とクリティカルアップで冒険を阻む壁を打ち崩す。", 0, 123201, 1, 0, "アヤネ（エクスプローラー）", 3, 3, 123201, 0, 0, 256, 123201, 1.425, "2022/09/15 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (123301, 1, "2026/09/30 11:59:59", "ねあ", "【物理】中衛で粘液を振りまくキイロいスライムギャル。\nスキルで敵全体の物理攻撃能力やＴＰ上昇を低下させ、\nＵＢでスライム化し全敵を攻撃しつつ無敵ボディを得る。", 0, 123301, 1, 0, "ネア", 0, 3, 123301, 0, 0, 350, 123301, 1.62, "2026/09/22 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (123401, 5, "2030/12/31 15:00:00", "じゅん", "", 0, 123401, 0, 0, "ジュン（キャンプ）", 5, 3, 0, 0, 0, 0, 0, 0.0, "2015/04/01 15:00:00", 0, 0, 0, 0, 0, 0);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (123501, 6, "2030/12/31 15:00:00", "りん", "【物理】中衛で敵を悪戯で翻弄する恐怖のキョンシー娘。\n最も魔法攻撃力が高い敵に急襲を仕掛け、ＴＰ減少や魔法\n攻撃力ダウン、スタン等の妨害スキルで機先を制する。", 0, 123501, 1, 0, "リン（ハロウィン）", 6, 1, 123501, 0, 0, 583, 123501, 2.34, "2024/09/17 15:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (123601, 4, "2025/11/30 11:59:59", "とも", "【物理】前衛で、同志と力を合わせ共に戦う夜廻り剣士。\n自分と物理攻撃力が最も高い味方１キャラの攻撃力を大幅\nに上昇させ、目にもとまらぬ剣技で不届き者を成敗する。", 0, 123601, 1, 0, "トモ（ハロウィン）", 4, 3, 123601, 0, 0, 262, 123601, 1.965, "2025/11/14 15:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (123701, 7, "2030/12/31 15:00:00", "ななか", "【魔法】後衛で、オタ活に精を出すハロウィン魔法少女。\nＨＰ回復量ダウンで敵の戦略を崩し、ダメージフィールド\nと対象の数で火傷の威力を増す熱狂の炎が敵を包み込む。", 0, 123701, 2, 0, "ナナカ（ハロウィン）", 21, 3, 123701, 0, 0, 741, 123701, 2.07, "2022/10/15 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (123801, 1, "2025/11/14 14:59:59", "くりすてぃーな", "【物理】前衛で、戦場を跳ね回るラビット姿の誓約女君。\n物理攻撃を全て回避するスキルと攻撃力の強化で敵陣に\n単身特攻をかけ、ＵＢの範囲攻撃で敵を内から薙ぎ倒す。", 0, 123801, 1, 0, "クリスティーナ（ワイルド）", 1, 3, 123801, 0, 0, 238, 123801, 2.295, "2025/11/03 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (123901, 2, "2030/12/31 15:00:00", "まつり", "【物理】前衛で母製の鎧を纏い気合い上々の獣人族騎士。\n自分のＨＰが低いほど与えるダメージと無効バリアの耐久\n力を高め、防御力ダウンと永続攻撃アップで活路を拓く。", 0, 123901, 1, 0, "マツリ（ワイルド）", 2, 3, 123901, 0, 0, 183, 123901, 2.125, "2022/11/15 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (124001, 7, "2025/12/31 11:59:59", "あかり", "【魔法】中衛で、聖夜の街に幸せを運ぶ双子の妹サンタ。\n自分の魔法攻撃力に応じて効果が上がる味方全体への攻撃\n力強化に加え、単体特大魔法攻撃で勝利の旋律を奏でる。", 0, 124001, 2, 0, "アカリ（クリスマス）", 7, 3, 124001, 0, 0, 438, 124001, 2.07, "2025/12/21 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (124101, 6, "2030/12/31 15:00:00", "より", "【魔法】中衛で、光を灯し幸せを届ける双子の姉サンタ。\n最も近い１キャラの魔法攻撃力や行動速度アップ、ＴＰの\n回復に加え、全員を支援するスキルで聖夜の勝利を飾る。", 0, 124101, 2, 0, "ヨリ（クリスマス）", 6, 1, 124101, 0, 0, 433, 124101, 1.965, "2024/11/16 15:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (124201, 5, "2030/12/31 15:00:00", "じゅん", "【物理】前衛で、味方を庇護し祝福する聖白の騎士団長。\nスキルで後方の味方の攻撃能力を強化、ＴＰを回復させ、\n防御力ダウンと自分のＨＰを回復するＵＢで勝機を掴む。", 0, 124201, 1, 0, "ジュン（クリスマス）", 5, 3, 124201, 0, 0, 144, 124201, 2.07, "2022/12/23 12:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (124301, 0, "2030/12/31 15:00:00", "あん", "", 0, 124301, 0, 1, "アン（アン＆グレア）", 0, 3, 0, 0, 0, 577, 0, 0.0, "2015/04/01 15:00:00", 0, 181001, 0, 0, 1, 0);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (124401, 0, "2030/12/31 15:00:00", "ぐれあ", "", 0, 124401, 0, 1, "グレア（アン＆グレア）", 0, 3, 0, 0, 0, 577, 0, 0.0, "2015/04/01 15:00:00", 0, 181001, 0, 0, 1, 0);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (124501, 7, "2026/01/31 11:59:59", "ほまれ", "【魔法】後衛で、魔力を笑顔に隠す晴れ着姿の龍の首魁。\n自分の攻撃強化とＴＰ回復をし、ＵＢで放つ曙光の落涙は\n敵数で威力と防御力の減少量を上げ、全ての災厄を祓う。", 0, 124501, 2, 0, "ホマレ（ニューイヤー）", 21, 3, 124501, 0, 0, 707, 124501, 2.07, "2026/01/15 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (124601, 7, "2026/01/31 11:59:59", "みさと", "【魔法】後衛で真心重ねて味方をもてなす仲居姿の先生。\n全スキルで味方の物理攻撃力とクリティカル能力を上げ、\n魔防やＴＰ上昇の支援とＨＰ、ＴＰの回復で万福を願う。", 0, 124601, 2, 0, "ミサト（ニューイヤー）", 21, 3, 124601, 0, 0, 698, 124601, 2.44, "2026/01/15 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (124701, 7, "2030/12/31 15:00:00", "みつき", "【物理】中衛で、振袖姿で旅館に手を貸す隻眼の闇医者。\n朧ろ状態にした敵への攻撃時、スキルのダメージや防御力\nのダウン値が上昇し、紫煙に捉えた敵を艶然と討ち取る。", 0, 124701, 1, 0, "ミツキ（ニューイヤー）", 46, 1, 124701, 0, 0, 590, 124701, 2.24, "2024/12/16 15:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (124801, 4, "2026/02/09 11:59:59", "のぞみ", "【物理】中衛で、未来を信じ希望を灯すトップアイドル。\nバトル開始時に物理キャラのＴＰ特大回復と敵の永続物防\nダウンで加勢し、物理攻撃強化とＴＰ回復で勝利へ導く。", 0, 124801, 1, 0, "ノゾミ（リベレイター）", 0, 3, 124801, 0, 0, 423, 124801, 2.14, "2026/01/31 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (124901, 1, "2030/12/31 15:00:00", "かや", "【物理】前衛で先陣を切り未来を掴む喧嘩屋ドラゴン族。\n初弾が大幅強化するスキルで自分の攻撃力とＴＰを大きく\n高め、威力を増したＵＢで先制し群がる敵を薙ぎ払う。", 0, 124901, 1, 0, "カヤ（リベレイター）", 0, 1, 124901, 0, 0, 170, 124901, 1.965, "2025/01/16 15:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (125001, 5, "2026/02/09 11:59:59", "むいみ", "【物理】前衛で、相棒と共に明日へと進む大悪党の少女。\n自己強化や物防ダウンを駆使するムイミと、ＵＢ後に一定\n時間共闘するオクトーの追撃で、輝く未来を取り戻す。", 0, 125001, 1, 0, "ムイミ（リベレイター）", 0, 3, 125001, 0, 0, 221, 125001, 1.965, "2026/01/31 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (125101, 8, "2030/12/31 15:00:00", "たまき", "【物理】後衛から客を癒しもてなす猫カフェ店員の猫娘。\n物攻の高いキャラの傍で周囲の物攻アップやＨＰとＴＰを\n回復し、周囲の味方数で強化される攻撃で敵を一掃する。", 0, 125101, 1, 0, "タマキ（カフェ）", 47, 3, 125101, 0, 0, 825, 125101, 2.24, "2023/03/03 19:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (125201, 4, "2030/12/31 15:00:00", "もにか", "【物理】中衛で、駄菓子を振舞い福を蒔く猫カフェ店員。\n攻撃を３回受けるまで味方全体の物理攻撃力を極大アップ\nさせ、２種の物防ダウンスキルで序盤を一気に加勢する。", 0, 125201, 1, 0, "モニカ（カフェ）", 4, 3, 125201, 0, 0, 463, 125201, 1.965, "2023/03/10 12:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (125301, 6, "2026/04/15 11:59:59", "こっころ", "【物理】後衛で、わんわんと一緒の新緑レンジャー少女。\n自分の攻撃力に応じて強化される物理攻撃支援スキルや\nＨＰ継続回復、バリアで周囲を支え、絆の勝利へと導く。", 0, 125301, 1, 0, "コッコロ（レンジャー）", 6, 3, 125301, 0, 0, 752, 125301, 2.07, "2026/03/31 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (125401, 8, "2030/12/31 15:00:00", "しおり", "【物理】後衛で、相棒と共に山を駆ける新米レンジャー。\nスキルで自分の攻撃力とクリティカル時のダメージを上げ\nＴＰを回復し、ダメージと防御力ダウンで敵を追い込む。", 0, 125401, 1, 0, "シオリ（レンジャー）", 8, 3, 125401, 0, 0, 710, 125401, 2.09, "2023/04/10 12:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (125501, 7, "2026/05/31 11:59:59", "じーた", "【魔法】中衛で、他の術者と魔力を束ねる究竟の魔導士。\n味方への魔法攻撃支援とＴＰ回復に加え、敵陣の攻防両面\nの弱体化で戦況を整え、自らも強力な攻撃魔法を放つ。", 0, 125501, 2, 0, "ジータ（ウォーロック）", 50, 3, 125501, 0, 0, 443, 125501, 1.92, "2026/05/22 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (125601, 51, "2026/05/31 11:59:59", "びから", "【物理】前衛で夢と希望とネズ耳を届ける鼠神宮の巫女。\n周囲の味方の物理攻撃支援、ＴＰ上昇アップと回復で援護\nし、自身の無敵化で敵の隙を突き鋭い金牙の一撃を放つ。", 0, 125601, 1, 0, "ビカラ", 0, 3, 125601, 0, 0, 267, 125601, 2.09, "2026/05/22 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (125701, 7, "2030/12/31 15:00:00", "かりん", "【魔法】中衛で森羅万象を究め味方を支援する錬金術師。\n物理、魔法の属性を問わない敵の弱体化と味方の強化に加\nえ、スキルによる高頻度のＨＰ回復で盤石な戦局を築く。", 0, 125701, 2, 0, "カリン（アルケミスト）", 9, 1, 125701, 0, 0, 579, 125701, 2.24, "2025/04/16 15:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (125801, 3, "2030/12/31 15:00:00", "りり", "【物理】中衛で、黒羽の力を使い空を制する嘆鎌の少女。\nバトル開始時に、敵の範囲攻撃を躱す【飛行】状態となり\n生成したシャドウと共に、眼前の敵を一薙ぎに斬り払う。", 0, 125801, 1, 0, "リリ（フォールン）", 0, 3, 125801, 0, 0, 464, 125801, 2.09, "2023/04/17 12:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (125901, 1, "2030/12/31 15:00:00", "かや", "", 0, 125901, 0, 0, "カヤ（リベレイター）", 1, 3, 0, 0, 0, 0, 0, 0.0, "2015/04/01 15:00:00", 0, 0, 0, 0, 1, 0);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (126001, 0, "2030/12/31 15:00:00", "くりあ", "【物理】中衛から、我が身を盾に味方を守る隠棘の少女。\nバトル開始時【飛行】し、最もＨＰの低い味方をかばい、\n味方のＨＰに応じて強化されるスキルで敵を牽制する。", 0, 126001, 1, 0, "クリア（フォールン）", 0, 3, 126001, 0, 0, 406, 126001, 2.09, "2023/10/31 12:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (126101, 44, "2030/12/31 15:00:00", "ぷれしあ", "【魔法】中衛で、マイペースに味方を支える破杖の少女。\n【飛行】し、クリティカルの強化やＨＰ・ＴＰ回復で味方\nを支援し、魔法攻撃力を加えた物理攻撃で敵を平らげる。", 0, 126101, 2, 0, "プレシア（フォールン）", 53, 3, 126101, 0, 0, 480, 126101, 2.09, "2023/11/15 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (126201, 3, "2026/06/30 11:59:59", "いりや", "【魔法】中衛で、眷属と永久の血盟を誓う月下の吸血鬼。\nＵＢで眷属を２体喚び、味方への攻撃支援や行動速度上昇\nで強化し、眷属と共に見舞う猛攻で前途を阻む敵を討つ。", 0, 126201, 2, 0, "イリヤ（儀装束）", 3, 3, 126201, 0, 0, 568, 126201, 2.09, "2026/06/22 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (126301, 7, "2030/12/31 15:00:00", "ゆき", "【魔法】中衛で、闇色の儀装束を纏う「美を統べる者」。\nステータスアップ効果を受け【美貌】を増し、魔法攻撃力\nダウンや味方の強化、ＴＰ回復の効果を高めて解き放つ。", 0, 126301, 2, 0, "ユキ（儀装束）", 9, 3, 126301, 0, 0, 456, 126301, 2.07, "2023/06/15 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (126401, 1, "2026/08/26 11:59:59", "くろーちぇ", "【物理】中衛で着脱可能な鉄腕を放つ機械人族のロボ娘。\nＵＢ発動で【フルチャージ】状態になり、【バッテリー】\nが切れるまで強化スキルを連発し、一帯を超速圧砕する。", 0, 126401, 1, 0, "クローチェ", 1, 3, 126401, 0, 0, 373, 126401, 2.09, "2026/08/23 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (126501, 7, "2026/08/26 11:59:59", "らいらえる", "【魔法】後衛で優美にほほ笑むジオ・テオゴニアの姫君。\n開始時に発動する【界雷】で、敵味方に影響を与えつつ、\n魔法防御ダウンと強力なダメージスキルで裁きを下す。", 0, 126501, 2, 0, "ライラエル", 0, 3, 126501, 0, 0, 740, 126501, 1.965, "2026/08/23 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (126601, 7, "2026/07/31 11:59:59", "ねねか", "【魔法】後衛で、涼しげに微笑む夏色姿の『変貌大妃』。\nスキルで味方を大幅に強化し、最も魔法攻撃力が高い味方\nの魔法攻撃力を写し取った攻撃力で、強力なＵＢを放つ。", 0, 126601, 2, 0, "ネネカ（サマー）", 7, 3, 126601, 0, 0, 650, 126601, 2.04, "2026/07/15 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (126701, 5, "2030/12/31 15:00:00", "あきの", "【物理】前衛で、優雅なバカンスを過ごす夕映えの令嬢。\n敵が魔法攻撃をする場合に効果を大幅に上げる２種の範囲\n攻撃と攻防両面の支援スキルで、盛夏の勝鬨を上げる。", 0, 126701, 1, 0, "アキノ（サマー）", 5, 1, 126701, 0, 0, 224, 126701, 1.965, "2025/06/17 15:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (126801, 5, "2030/12/31 15:00:00", "ゆかり", "【物理】前衛で、夏の麦しゅわを嗜むビーチの元聖騎士。\n敵単体にダメージを与えながら、周囲の味方への魔法無効\nバリア付与と魔防アップで守りを固めて勝利の波に乗る。", 0, 126801, 1, 0, "ユカリ（サマー）", 5, 3, 126801, 0, 0, 159, 126801, 1.97, "2023/07/15 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (126901, 7, "2026/08/31 11:59:59", "らんふぁ", "【魔法】後衛で、密やかな潮騒に耳を傾ける晩陽の歌姫。\n魔法クリティカルの極大アップを筆頭に攻防両面で周囲の\n味方を強化し、さらに自身もＵＢで数多の敵を退かせる。", 0, 126901, 2, 0, "ランファ（サマー）", 21, 3, 126901, 0, 0, 682, 126901, 1.965, "2026/08/26 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (127001, 2, "2030/12/31 15:00:00", "くうか", "【物理】前衛で新たな刺激を追い求める水着姿のドＭ娘。\n自分のＨＰが下がるほど効果量が上昇するスキルの物理攻\n撃力アップとＵＢのダメージで、勝利の大海へ飛び込む。", 0, 127001, 1, 0, "クウカ（サマー）", 52, 1, 127001, 0, 0, 133, 127001, 1.97, "2025/07/16 15:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (127101, 5, "2026/08/31 11:59:59", "しのぶ", "【物理】前衛で、穏やかな水面に揺蕩う夜光の霊能少女。\n召喚した親父に敵の攻撃を引き付けさせつつ、シノブ自身\nの攻撃性能強化と防御ダウンを扱い、敵を冥海へと誘う。", 0, 127101, 1, 0, "シノブ（サマー）", 46, 3, 127101, 0, 0, 255, 127101, 2.09, "2026/08/26 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (127201, 7, "2025/09/30 11:59:59", "きゃる", "【魔法】後衛で、制服姿に胸を高鳴らせるアオハル猫娘。\n攻防両面のサポートに加え行動速度アップとＴＰ回復で味\n方を支援し、最も遠くの敵を狙うＵＢで輝く勝利を得る。", 0, 127201, 2, 0, "キャル（編入生）", 7, 3, 127201, 0, 0, 804, 127201, 2.09, "2025/09/16 15:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (127301, 8, "2030/12/31 15:00:00", "すずな", "【物理】後衛でもにカワ制服を着こなすカリスマモデル。\nクリティカル時に味方を強化するスキルや、追加ダメージ\nが発生するＵＢによって青春の一ページを切り取る。", 0, 127301, 1, 0, "スズナ（編入生）", 8, 3, 127301, 0, 0, 750, 127301, 2.09, "2023/09/15 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (127401, 1, "2030/12/31 15:00:00", "びから", "", 0, 127401, 0, 0, "ビカラ（コラボ）", 1, 3, 0, 0, 0, 0, 0, 0.0, "2015/04/01 15:00:00", 0, 0, 0, 0, 1, 0);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (127501, 4, "2026/02/09 11:59:59", "されん", "【物理】中衛で、優艶に炎と踊り舞う情熱のサレンママ。\n物理攻撃から味方を守り、【炎舞の刻印】の数に応じて効\n果の上がる物攻アップとＴＰ回復で皆を奮い立たせる。", 0, 127501, 1, 0, "サレン（サラサリア）", 4, 3, 127501, 0, 0, 304, 127501, 2.09, "2026/01/31 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (127601, 4, "2030/12/31 15:00:00", "るか", "【物理】前衛で、空飛ぶ絨毯で巡り回るオアシスの姉御。\n自分の物防を大幅に高めて敵を挑発するスキルと敵のＴＰ\nとＴＰ上昇をダウンさせるＵＢで、爽やかに勝利を掴む。", 0, 127601, 1, 0, "ルカ（サラサリア）", 4, 3, 127601, 0, 0, 157, 127601, 1.965, "2023/10/15 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (127701, 6, "2030/12/31 15:00:00", "りんど", "【魔法】後衛で、メイド業に奔走する双子ドラゴンの姉。\nＵＢのフィールド展開中は攻撃、防御、ＴＰ回復と多彩な\n支援スキルの効果が再発動し味方を手厚くサポートする。", 0, 127701, 2, 0, "リンド", 48, 3, 127701, 0, 0, 693, 127701, 1.965, "2024/10/10 12:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (127801, 7, "2030/12/31 15:00:00", "うるむ", "【魔法】後衛で、文句を言いつつ働く双子ドラゴンの妹。\nダメージと魔法防御力ダウンを両立するスキルを持つが、\n目を離すと【サボりの誘惑】に負け、手を抜いてしまう。", 0, 127801, 2, 0, "ヴルム", 47, 3, 127801, 0, 0, 706, 127801, 1.965, "2024/10/18 12:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (127901, 5, "2025/12/31 11:59:59", "ぺこりーぬ", "【魔法】中衛でみんなに笑顔を届ける腹ペコサンタ王女。\n前線で敵の攻撃を耐えながら範囲内の味方の防御サポート\nと敵の防御ダウンまでこなし、聖夜に勝利の輝きを灯す。", 0, 127901, 2, 0, "ペコリーヌ（クリスマス）", 5, 3, 127901, 0, 0, 372, 127901, 1.965, "2025/12/21 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (128001, 35, "2030/12/31 15:00:00", "くれじった", "【物理】後衛で、甘美なひと時を堪能する聖夜の女商人。\n最も遠い味方へのＴＰ回復や、初弾に追加効果のある攻撃\nで敵の弱体化と味方の強化を行い、勝利の舞台を整える。", 0, 128001, 1, 0, "クレジッタ（クリスマス）", 35, 3, 128001, 0, 0, 723, 128001, 2.09, "2023/12/15 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (128101, 0, "2030/12/31 15:00:00", "しずる", "", 0, 128101, 0, 1, "シズル（シズル&リノ）", 0, 3, 0, 0, 0, 580, 0, 0.0, "2015/04/01 15:00:00", 0, 181101, 0, 0, 1, 0);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (128201, 0, "2030/12/31 15:00:00", "りの", "", 0, 128201, 0, 1, "リノ（シズル&リノ）", 0, 3, 0, 0, 0, 580, 0, 0.0, "2015/04/01 15:00:00", 0, 181101, 0, 0, 1, 0);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (128301, 3, "2030/12/31 15:00:00", "いのり", "【物理】前衛で相手をからかうお調子者の年神ドラゴン。\n敵全体を挑発し、敵の妨害スキルにカウンターして前方の\n敵すべてをスタンさせるスキルで戦局を引っ掻き回す。", 0, 128301, 1, 0, "イノリ（ニューイヤー）", 38, 1, 128301, 0, 0, 191, 128301, 2.09, "2026/01/16 15:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (128401, 7, "2026/01/31 11:59:59", "はつね", "【魔法】後衛で特別な景色を共にする初夢超能力ガール。\n敵が物理攻撃を行う場合、攻撃性能の強化に加えて複数の\n弱体効果が追加され、攻守ともに味方を支援し敵を掃う。", 0, 128401, 2, 0, "ハツネ（ニューイヤー）", 21, 3, 128401, 0, 0, 801, 128401, 2.09, "2026/01/15 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (128501, 7, "2026/01/31 11:59:59", "かすみ", "【魔法】後衛で、絵馬に秘めた願いを祷る新年の名探偵。\n敵と味方の数で効果量が上昇するダメージと攻撃力支援に\n加え、２種類の回復スキルを使いこなして勝利を願う。", 0, 128501, 2, 0, "カスミ（ニューイヤー）", 21, 3, 128501, 0, 0, 739, 128501, 2.09, "2026/01/15 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (128601, 1, "2030/12/31 15:00:00", "りり", "", 0, 128601, 0, 0, "リリ（フォールン）", 1, 3, 0, 0, 0, 0, 0, 0.0, "2015/04/01 15:00:00", 0, 0, 0, 0, 1, 0);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (128701, 1, "2026/02/09 11:59:59", "ひより", "【物理】前衛で、煌炎宿し希望を振りまく覚醒の元気娘。\n放つ炎は敵を攻守ともに弱化させて同時に味方を鼓舞し、\n２種のＴＰ回復効果で攻勢を絶やさず勝利を呼び込む。", 0, 128701, 1, 0, "ヒヨリ（アストラル）", 0, 3, 128701, 0, 0, 226, 128701, 2.09, "2026/01/31 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (128801, 4, "2030/12/31 15:00:00", "れい", "【物理】前衛で、旋風を纏い未来へ駆ける覚醒の剣士。\n目にも止まらぬ速さの剣技で敵を吹き飛ばしスタンさせ、\n仲間の守りを固めるスキルを駆使し勝利の道を切り開く。", 0, 128801, 1, 0, "レイ（アストラル）", 0, 1, 128801, 0, 0, 194, 128801, 1.965, "2025/08/16 15:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (128901, 7, "2026/02/09 11:59:59", "ゆい", "【魔法】後衛で、願いを力に極光を放つ覚醒の魔法士。\n自分を強化しながら高火力魔法を絶えず撃ち込み、バリア\nを起点とした味方への攻撃支援スキルで勝利を手にする。", 0, 128901, 2, 0, "ユイ（アストラル）", 0, 3, 128901, 0, 0, 772, 128901, 2.09, "2026/01/31 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (129001, 7, "2026/08/26 11:59:59", "えりす", "【魔法】後衛で、眠りから目覚め美しく咲き誇る黒薔薇。\n終焉を超えし【回帰の薔薇】と、行動速度アップを始めと\nした多種の攻防支援で味方を強化し、新たな未来を掴む。", 0, 129001, 2, 0, "エリス", 0, 3, 129001, 0, 0, 800, 129001, 2.09, "2026/08/23 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (129301, 7, "2026/03/31 11:59:59", "ゆに", "【物理】後衛で、退廃的な冬の学びに溺れる水際の才媛。\n物理攻撃の強化、回復、行動速度アップで味方を支援し、\nＵＢで得た【水際の安寧】を死守するため膂力を振るう。", 0, 129301, 1, 0, "ユニ（ウィンター）", 7, 3, 129301, 0, 0, 708, 129301, 2.09, "2026/03/16 10:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (129401, 2, "2030/12/31 15:00:00", "くろえ", "【物理】前衛で、水面に映る神速のダウナー系水着女子。\n攻撃を当てる度に敵に付与する【水月】の数に応じて物防\nダウンやダメージの効果が上昇し、必勝の抜き手を切る。", 0, 129401, 1, 0, "クロエ（ウィンター）", 2, 3, 129401, 0, 0, 188, 129401, 2.09, "2024/03/18 12:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (129501, 1, "2025/12/15 14:59:59", "ちえる", "【物理】前衛で、ちぇるっとちぇるるな水着のちえるん。\nステータスアップで溜まる【ちぇる】を、自身の火力や\n支援能力に還元して、真冬の真夏をちぇらるれれぽぱぴ？", 0, 129501, 1, 0, "チエル（ウィンター）", 1, 3, 129501, 0, 0, 247, 129501, 2.09, "2025/11/30 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (129601, 0, "2026/08/26 11:59:59", "あねもね", "【物理】中衛で怜悧麗花の陣を張るアルラウネの妖魔人。\n敵の攻撃力、防御力、与ダメージを下げ、ＴＰを吸収し、\nＵＢの継続ダメージで領域を侵す敵を絶えず拒み退ける。", 0, 129601, 1, 0, "アネモネ", 0, 3, 129601, 0, 0, 550, 129601, 2.09, "2026/08/23 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (129701, 0, "2026/08/26 11:59:59", "ねふぃーねら", "【物理】中衛で万魔の頂点に君臨するジオ・ゲヘナの媛。\n環境効果【妨魔塵】で魔法攻撃を阻害し、行動速度アップ\n等の支援や苛烈な攻撃で無謀な不届き者を平伏させる。", 0, 129701, 1, 0, "ネフィ＝ネラ", 0, 3, 129701, 0, 0, 540, 129701, 2.09, "2026/08/23 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (129801, 5, "2026/04/15 11:59:59", "まこと", "【物理】前衛で、情と熱意で仲間を束ねる指揮官の狼娘。\n敵の攻守を削りつつ、自分のＴＰ回復や対象が物防ダウン\n状態の時に発生する追撃で猛攻を仕掛け前線を突破する。", 0, 129801, 1, 0, "マコト（コマンダー）", 5, 3, 129801, 0, 0, 269, 129801, 2.09, "2026/03/31 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (129901, 6, "2030/12/31 15:00:00", "えりこ", "【物理】前衛で、苛烈な教えで味方を率いる狂恋の教官。\nＴＰ回復や防御支援に加え味方の人数で効果アップする攻\n撃支援と大ダメージで、味方全体を奮い立たせ敵を破る。", 0, 129901, 1, 0, "エリコ（コマンダー）", 48, 3, 129901, 0, 0, 294, 129901, 1.84, "2024/04/15 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (130001, 4, "2025/11/14 14:59:59", "やまと", "【物理】前衛で、豪胆にスリルを嗜む盗賊ギルドの長女。\n最前線で命を張りながら、獲得した【バンディダイス】の\n消費によって自らを大幅強化し、有象無象を地に伏せる。", 0, 130001, 1, 0, "ヤマト", 0, 3, 130001, 0, 0, 150, 130001, 2.09, "2025/11/03 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (130101, 7, "2025/11/14 14:59:59", "わかな", "【物理】中衛の、貧乏クジを引きがちな盗賊ギルド次女。\n召喚したスキッドがワカナをかばって前線に立ち、自身は\n攻撃支援にＨＰとＴＰ回復まで、献身的に味方を支える。", 0, 130101, 1, 0, "ワカナ", 9, 3, 130101, 0, 0, 535, 130101, 2.09, "2025/11/03 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (130201, 5, "2025/11/14 14:59:59", "ふぶき", "【物理】中衛の、ナマイキで超天才な盗賊ギルドの三女。\n【味方バリアー♡】で自分へのダメージを味方に押し付け\nＨＰ最大でダメージアップする範囲攻撃で敵を蹂躙する。", 0, 130201, 1, 0, "フブキ", 0, 3, 130201, 0, 0, 371, 130201, 1.84, "2025/11/03 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (130601, 4, "2030/12/31 15:00:00", "れい", "", 0, 130601, 0, 0, "レイ（アストラル）", 1, 3, 0, 0, 0, 0, 0, 0.0, "2015/04/01 15:00:00", 0, 0, 0, 0, 1, 0);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (130701, 7, "2026/05/31 11:59:59", "きょうか", "【魔法】中衛で、お花畑に春を届ける花衣装の優等生。\nスキル発動回数に応じた効率的な自己強化やクリティカル\n時の追加効果を持つスキルとＵＢで勝利の風を吹かせる。", 0, 130701, 2, 0, "キョウカ（スプリング）", 7, 3, 130701, 0, 0, 563, 130701, 1.92, "2026/05/22 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (130801, 7, "2030/12/31 15:00:00", "すずめ", "【魔法】中衛で、春に彩られた花衣装のドジっ娘メイド。\n範囲内の敵にダメージを与えながら、多数の弱体化効果を\n持つスキルやＵＢを駆使して、穏やかに吹く勝利を掴む。", 0, 130801, 2, 0, "スズメ（スプリング）", 7, 3, 130801, 0, 0, 558, 130801, 1.84, "2024/05/15 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (130901, 7, "2030/12/31 15:00:00", "くるる", "【魔法】中衛で、皆を夢の世界に誘う宝石兎族の支配人。\nステータスアップ効果を受けるたびに【かばばん君】を増\nやし、反射的に味方へ攻撃支援の恩返しをしてしまう。", 0, 130901, 2, 0, "クルル", 7, 3, 130901, 0, 0, 440, 130901, 2.09, "2024/06/15 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (131001, 7, "2026/06/30 11:59:59", "まほ", "【魔法】後衛で、サーカスの舞台に輝くメルヘン少女。\n味方の攻防支援や敵の攻防弱体化の他【カーテンコール】\n付与時の追加ダメージスキルで、勝利のライトを照らす。", 0, 131001, 2, 0, "マホ（ドリームパーク）", 7, 3, 131001, 0, 0, 702, 131001, 1.84, "2026/06/22 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (131101, 2, "2030/12/31 15:00:00", "ねあ", "【物理】前衛でハグの機会を窺う水着のスライムギャル。\n攻撃してきた敵に【ネバネバ】を自動で付着させ、攻撃力\nダウンやダメージ、束縛など複数の効果を引き起こす。", 0, 131101, 1, 0, "ネア（サマー）", 52, 3, 131101, 0, 0, 165, 131101, 2.09, "2024/06/30 12:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (131201, 54, "2026/07/31 11:59:59", "みそら", "【魔法】後衛で夏の盛りにイイコトをする溌溂水着少女★\n【PSI★ストーム】をチャージし、連続攻撃で敵を殲滅し\nて、継続ＴＰ回復やバリアで抜け目なく味方を支援する。", 0, 131201, 2, 0, "ミソラ（サマー）", 54, 3, 131201, 0, 0, 753, 131201, 2.09, "2026/07/15 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (131301, 1, "2030/12/31 15:00:00", "りり", "", 0, 131301, 0, 1, "リリ", 1, 3, 0, 0, 0, 0, 0, 0.0, "2015/04/01 15:00:00", 0, 0, 0, 0, 1, 0);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (131401, 1, "2030/12/31 15:00:00", "くりあ", "", 0, 131401, 0, 1, "クリア", 1, 3, 0, 0, 0, 0, 0, 0.0, "2015/04/01 15:00:00", 0, 0, 0, 0, 1, 0);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (131501, 1, "2030/12/31 15:00:00", "ぷれしあ", "", 0, 131501, 0, 1, "プレシア", 1, 3, 0, 0, 0, 0, 0, 0.0, "2015/04/01 15:00:00", 0, 0, 0, 0, 1, 0);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (131601, 4, "2026/07/31 11:59:59", "りり", "【物理】中衛で、夏の陽光のもと研鑽する妹系大和撫子。\n防御力アップに加えバリアやＨＰ回復で味方の守りを固め\nＴＰ回復や攻撃力ダウンをも巧みに操り、場を支配する。", 0, 131601, 1, 0, "リリ（サマー）", 4, 3, 131601, 0, 0, 399, 131601, 1.92, "2026/07/15 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (131701, 44, "2026/08/31 11:59:59", "あめす", "【魔法】後衛で、黄昏の水面に舞い降りる水着姿の妖精。\n行動速度アップやＴＰ支援をはじめとした多数のサポート\nを施しつつ、ＵＢの攻防弱体化で清爽に勝利へと導く。", 0, 131701, 2, 0, "アメス（サマー）", 53, 3, 131701, 0, 0, 743, 131701, 1.92, "2026/08/26 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (131801, 7, "2030/12/31 15:00:00", "ほまれ", "【魔法】後衛で夏の清涼に翼を休める水着姿の龍の首領。\n攻防弱体化に加え、ステータスダウン付与のたび増加する\n【日食】の数に応じたダメージで、抗う全てを灰に帰す。", 0, 131801, 2, 0, "ホマレ（サマー）", 21, 3, 131801, 0, 0, 709, 131801, 2.09, "2024/08/15 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (131901, 7, "2030/12/31 15:00:00", "えみりあ", "【魔法】後衛で、パックと共に戦う真夏のハーフエルフ。\n氷壁を生成するスキルや、強力なダメージと速度ダウンを\n付与するユニオンバーストで、敵の侵攻を食い止める。", 0, 131901, 2, 1, "エミリア（サマー）", 23, 1, 131901, 0, 0, 725, 131901, 2.09, "2024/08/31 12:00:00", 1, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (132001, 7, "2025/10/24 11:59:59", "えきどな", "【魔法】後衛で未知の世界との邂逅に胸躍る強欲の魔女。\n鮮烈な攻撃魔法をはじめ、味方への攻撃支援、敵の弱体化\nから自己蘇生まで、あらゆる魔法を振るい、欲を満たす。", 0, 132001, 2, 0, "エキドナ（サマー）", 21, 3, 132001, 0, 0, 775, 132001, 2.09, "2025/10/10 12:00:00", 1, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (132101, 13, "2025/10/24 11:59:59", "れむ", "【物理】前衛で夏の日差しの中、余暇を楽しむ双子の妹。\nＵＢで鬼族の力を解放すると攻防両面に加えＨＰ吸収が\n上昇し、目に映る全てを【狂騒】のままに叩き伏せる。", 0, 132101, 1, 0, "レム（サマー）", 24, 3, 132101, 0, 0, 146, 132101, 2.09, "2025/10/10 12:00:00", 1, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (132201, 7, "2025/10/31 11:59:59", "のぞみ", "【魔法】後衛で、希望を錬成するアルケミストアイドル。\n【錬金素材】から【パフューム】を創り、ダメージに加え\nＴＰ回復や攻撃支援能力を向上させて勝利の香りを運ぶ。", 0, 132201, 2, 0, "ノゾミ（アルケミスト）", 7, 3, 132201, 0, 0, 721, 132201, 1.84, "2025/10/24 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (132301, 7, "2026/05/22 11:59:59", "るいずまりー", "【魔法】後衛で、底知れぬ叡智を秘めた天才錬金術師。\n高い方の防御力でダメージを受ける調和状態を付与し、\n２回まで性能が上昇していくＵＢで、妄想を爆発させる。", 0, 132301, 2, 0, "ルイズマリー", 7, 3, 132301, 0, 0, 754, 132301, 2.09, "2026/05/11 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (132401, 5, "2030/12/31 15:00:00", "いろは", "【物理】中衛で、大きな体で無邪気に遊び回る天才剣士。\n戦いの中で【剣圧】を溜め、その後のスキルやＵＢで物防\n一定無視のダメージを連発し、才気煥発の活躍を見せる。", 0, 132401, 1, 0, "イロハ", 0, 3, 132401, 0, 0, 501, 132401, 2.09, "2025/06/20 12:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (132501, 7, "2030/12/31 15:00:00", "その", "【魔法】後衛で、小柄で大人対応な錬金堂の省エネ店主。\n強力な弱体効果を与えながら、デバフ付与のたび増加する\n【虚脱】が80溜まると本気を出し定時厳守で戦い抜く。", 0, 132501, 2, 0, "ソノ", 23, 3, 132501, 0, 0, 636, 132501, 2.09, "2025/05/15 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (132801, 7, "2025/12/15 14:59:59", "らいらえる", "【魔法】後衛で、雪白の肌を黒衣に包んだ甘美なる姫君。\n味方のＨＰを代償に強力なバリアを展開しつつ、バリアを\n起点とした高出力の二連撃で、聖夜の大樹に灯を点す。", 0, 132801, 2, 0, "ライラエル（クリスマス）", 0, 3, 132801, 0, 0, 750, 132801, 2.09, "2025/11/30 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (132901, 5, "2030/12/31 15:00:00", "いお", "【魔法】後衛で、心地良い眠りの中に訪れる聖夜の悪魔。\n最も魔法攻撃力が高い味方に【悪魔の口づけ】を付与し、\n攻撃支援とＴＰ回復による付きっきりの手ほどきをする。", 0, 132901, 2, 0, "イオ（クリスマス）", 46, 3, 132901, 0, 0, 748, 132901, 2.09, "2024/12/09 12:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (133001, 0, "2026/08/26 11:59:59", "ぐれいす", "【物理】前衛で、宙を舞うように戦う幽霊の守護騎士。\nＵＢで味方の攻撃と速度支援を行い、【レイスボディ】で\n敵の目を逃れ、不意を突く一撃で永遠の眠りにつかせる。", 0, 133001, 1, 0, "グレイス", 0, 3, 133001, 0, 0, 234, 133001, 2.09, "2026/08/23 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (133101, 0, "2026/08/26 11:59:59", "うぁいおれっと", "【物理】前衛で、儚くも凛と咲くジオ・ニヴルヘルの姫。\n継続ダメージ効果を鈍化させる環境効果【忌火】で盾に、\n絶怠霊度の継続割合攻撃で矛となり、静寂の冥府を護る。", 0, 133101, 1, 0, "ヴァイオレット", 0, 3, 133101, 0, 0, 154, 133101, 1.75, "2026/08/23 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (133201, 4, "2030/12/31 15:00:00", "もにか", "【物理】前衛で、元日も元気にはしゃぎまわる軍人少女。\n与ダメージに応じて追加効果が強化されるＵＢと、発動ご\nとに成長する自己強化スキルで秩序を乱す者の目を回す。", 0, 133201, 1, 1, "モニカ（ニューイヤー）", 22, 1, 133201, 0, 0, 296, 133201, 2.09, "2024/12/31 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (133501, 4, "2026/01/15 11:59:59", "されん", "【魔法】後衛で、傍らで心を重ねる振袖姿の救護院の主。\n味方へのＴＰ回復の支援をしつつ、味方がＵＢを発動する\nたびダメージが上がるスキルで、共に困難を乗り越える。", 0, 133501, 2, 0, "サレン（ニューイヤー）", 22, 3, 133501, 0, 0, 718, 133501, 2.09, "2026/01/03 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (133601, 0, "2026/01/15 11:59:59", "めどぅーさ", "【物理】中衛で眷属と力を合わせて戦う誇り高き蛇乙女。\n【魔眼】の数に応じて効果量が上がるスキルのダメージと\n弱体化で範囲内の敵を追い詰め、鋭い瞳で石へと変える。", 0, 133601, 1, 0, "メドゥーサ", 0, 3, 133601, 0, 0, 445, 133601, 2.09, "2026/01/03 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (133701, 8, "2026/02/15 11:59:59", "らびりすた", "【魔法】後衛で、始原の冠装を使いこなす『迷宮女王』。\n水属性の味方のＴＰ上昇を増加する領域を作り、連射攻撃\nで敵の防御を撃ち抜くことで七冠の力を敵に知らしめる。", 0, 133701, 2, 0, "ラビリスタ（アルファ）", 0, 3, 133701, 0, 0, 717, 133701, 2.09, "2026/02/09 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (133801, 7, "2026/02/15 11:59:59", "ねねか", "【魔法】後衛から、始原の姿で戦況を操る『変貌大妃』。\n召喚したグレゴールから攻撃支援とＴＰ回復を受け、互い\nの魔力を合わせた連携攻撃で、幽玄なる玉座に君臨する。", 0, 133801, 2, 0, "ネネカ（アルファ）", 0, 3, 133801, 0, 0, 759, 133801, 2.09, "2026/02/09 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (133901, 6, "2026/02/15 11:59:59", "くりすてぃーな", "【物理】前衛で、始原の冠装の力を振るう『誓約女君』。\n10行動目に攻撃力を大幅アップし、スキルに追撃を発生\nさせる【虚数】を得て隔絶した力で楯突く敵を抹消する。", 0, 133901, 1, 0, "クリスティーナ（アルファ）", 0, 3, 133901, 0, 0, 228, 133901, 2.09, "2026/02/09 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (134001, 0, "2026/08/26 11:59:59", "ふぃお", "【魔法】後衛で、アストルムの冒険へと導くガイド妖精。\nバフとバリアで味方を護りバリアを起点とする攻撃支援、\n風属性の味方への行動速度とＴＰの支援で仲間を支える。", 0, 134001, 2, 0, "フィオ", 0, 3, 134001, 0, 0, 746, 134001, 2.09, "2026/08/23 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (134101, 5, "2030/12/31 15:00:00", "ふぶき", "", 0, 134101, 0, 0, "フブキ", 1, 3, 0, 0, 0, 0, 0, 0.0, "2015/04/01 15:00:00", 0, 0, 0, 0, 1, 0);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (134201, 7, "2030/12/31 15:00:00", "らいらえる", "", 0, 134201, 0, 0, "ライラエル（クリスマス）", 1, 3, 0, 0, 0, 0, 0, 0.0, "2015/04/01 15:00:00", 0, 0, 0, 0, 1, 0);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (134301, 7, "2026/03/16 9:59:59", "らんふぁ", "【魔法】後衛で儀装束を纏い精霊と心を通わせる唱喚士。\n敵の数に応じてダメージ量が変化する範囲攻撃や、魔法\n無効バリアなどの支援スキルで想いを詩に乗せ響かせる。", 0, 134301, 2, 0, "ランファ（儀装束）", 0, 3, 134301, 0, 0, 778, 134301, 2.09, "2026/03/03 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (134401, 7, "2030/12/31 15:00:00", "ちか", "【魔法】後衛で儀装束を纏い歌を紡ぎ伝えていく唱喚士。\n自分と最も近くの味方へ強力なバフとＴＰ回復を行うこと\nで攻撃を支援し、共に心を通わせ美しき旋律を奏でる。", 0, 134401, 2, 0, "チカ（儀装束）", 21, 3, 134401, 0, 0, 773, 134401, 2.09, "2025/03/15 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (134501, 0, "2026/04/30 11:59:59", "くろーちぇ", "【魔法】後衛で超速飛行からの大火力を叩き込むロボ娘。\n上空から速度バフで味方全体を支援しつつ、自分のバリア\nを解除して力へと変え、世界の命運を背負い飛翔する！", 0, 134501, 2, 0, "クローチェ（エアリアル）", 0, 3, 134501, 0, 0, 719, 134501, 2.09, "2026/04/15 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (134601, 35, "2026/04/30 11:59:59", "あおい", "【物理】中衛で巨大ロボを駆り戦うぼっちのパイロット。\n敵の弱体化や、味方へバリアを展開するスキルを持ち、\n鋼鉄の乙女から放つ光線はいかに堅固な守りも打ち破る。", 0, 134601, 1, 0, "アオイ（パイロット）", 35, 3, 134601, 0, 0, 526, 134601, 2.09, "2026/04/15 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (134701, 7, "2026/04/30 11:59:59", "ほうおう", "【物理】中衛で、華麗に舞い踊る五色絢爛な煉華の鳳凰。\n攻撃力バフやバリア展開などの攻防支援と、多彩で豊富な\nＨＰ・ＴＰ供給を両立し、浄化の力で皆に安寧を授ける。", 0, 134701, 1, 0, "ホウオウ", 7, 3, 134701, 0, 0, 490, 134701, 2.09, "2026/04/15 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (134801, 1, "2026/06/22 11:59:59", "つむぎ", "【物理】中衛から、新たな素材で紡ぐワイルドテーラー。\n最も物攻が高い他の味方へ重複速度アップやＴＰ・攻撃支\n援を仕立て、全体へのＨＰ回復と併せ攻守を両立させる。", 0, 134801, 1, 0, "ツムギ（ジオ・ゲヘナ）", 1, 3, 134801, 0, 0, 485, 134801, 1.84, "2026/06/10 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (134901, 2, "2026/06/22 11:59:59", "かのん", "【物理】前衛で、おエレガントな高笑いを轟かすド令嬢。\nＵＢや敵からの攻撃で【お堪忍袋】が尽きると逆上し、強\n化されたスキルと行動パターンで華麗におリベンジする。", 0, 134901, 1, 0, "カノン", 0, 3, 134901, 0, 0, 196, 134901, 2.09, "2026/06/10 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (135001, 7, "2026/07/15 11:59:59", "えりす", "【魔法】後衛で、永く夢見た本物の夏に咲き綻ぶ黒薔薇。\n【いばらの冠】の呪縛は再臨により解き放たれ、調和状態\nや攻防支援、回復効果を施し、月下の浜辺に静かに佇む。", 0, 135001, 2, 0, "エリス（サマー）", 21, 3, 135001, 0, 0, 785, 135001, 2.09, "2026/07/03 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (135101, 4, "2026/07/15 11:59:59", "しぇふぃ", "【物理】前衛で盛夏の白波を華麗に乗りこなす氷竜少女。\n敵全体を挑発し、被弾で溜まる【ぐずぐず】をＵＢで発散\nすることで周囲に攻撃支援と天真爛漫な笑顔を振りまく。", 0, 135101, 1, 0, "シェフィ（サマー）", 4, 3, 135101, 0, 0, 143, 135101, 2.09, "2026/07/03 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (135201, 7, "2026/07/15 11:59:59", "ぷれしあ", "【魔法】中衛で夏の食を満喫し、ぷかぷか漂う天然少女。\nＴＰ・攻撃支援やバリアは味方の数で効果量が変化し、物\n理と魔法攻撃力合算のダメージで夏の思い出を心に刻む。", 0, 135201, 2, 0, "プレシア（サマー）", 7, 3, 135201, 0, 0, 548, 135201, 2.09, "2026/07/03 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (135301, 54, "2026/08/15 11:59:59", "くりあ", "【物理】中衛で友情の芽を育む、真夏の『普通』の少女。\n【プルメリアのお守り】で強力な一撃から先頭を守り、味\n方の数で効果量が変化するスキルを鮮やかに命中させる。", 0, 135301, 1, 0, "クリア（サマー）", 54, 3, 135301, 0, 0, 413, 135301, 2.09, "2026/07/31 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (135401, 2, "2026/08/15 11:59:59", "あねもね", "【魔法】中衛で砂浜の木陰に微睡むアルラウネの妖魔人。\n行動速度アップや初回発動時に回復量が増加するＴＰ回復\nを起点に支援し、穏やかな木漏れ日と共にゆらゆら憩う。", 0, 135401, 2, 0, "アネモネ（サマー）", 52, 3, 135401, 0, 0, 553, 135401, 2.09, "2026/07/31 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (135501, 1, "2026/08/26 11:59:59", "あいら", "【物理】前衛で、世界を守り笑顔を咲かせる情熱の豪炎。\n前方の敵全てを対象とする連撃の強化通常攻撃や、天楼覇\n断剣から放たれる極大ダメージの一閃で未来を切り拓く。", 0, 135501, 1, 0, "アイラ", 0, 3, 135501, 0, 0, 213, 135501, 2.09, "2026/08/23 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (135601, 4, "2026/08/26 11:59:59", "しなつ", "【物理】前衛から、風裂く刃で世界を護る孤高の剣豪。\n卓越した剣技で敵の攻撃を捌いて反撃し、初回ＵＢで生成\nする分身と共に疾風迅雷の攻めで、未来へと駆け抜ける。", 0, 135601, 1, 0, "シナツ", 0, 3, 135601, 0, 0, 198, 135601, 0.4, "2026/08/23 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (135701, 1, "2030/12/31 15:00:00", "ひより", "【物理】前衛で、二人きりの月下の空旅にときめく黒猫。\n物防弱体の他、ダメージ100ヒット後には華麗なステップ\nの追撃とＴＰ回復量増加で、砂漠の夜空に花を咲かせる。", 0, 135701, 1, 0, "ヒヨリ（サラサリア）", 0, 3, 135701, 0, 0, 291, 135701, 1.84, "2025/09/16 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (135801, 7, "2026/10/15 11:59:59", "ゆきの", "【魔法】後衛から、雪魄氷姿の三味を弾じる初心な雪女。\n多様なデバフ効果で敵を弱体化させ、最も魔防の低い敵の\n状態に応じて発生する追加効果で、冥府を真白に染める。", 0, 135801, 2, 0, "ユキノ", 0, 3, 135801, 0, 0, 830, 135801, 2.09, "2026/09/30 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (135901, 3, "2026/10/15 11:59:59", "さつき", "【物理】前衛で、華奢な体躯に厚い仁義を宿す鬼のお嬢。\n攻防自己強化や行動不能無効化で豪胆に立ち続け、自分が\n呪詛状態の時に振るう追加攻撃で、怪力無双の力を示す。", 0, 135901, 1, 0, "サツキ", 0, 3, 135901, 0, 0, 219, 135901, 1.84, "2026/09/30 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (136001, 11, "2026/08/26 11:59:59", "あらくね", "【物理】後衛で、喪われた光を求めてもがく元『六凶』。\n敵のＵＢを遅延する【遮絶の操糸】や、味方単体のＵＢを\n連続発動可能にする【賦活の糸】を戦場に張り巡らせる。", 0, 136001, 1, 0, "アラクネ", 0, 3, 136001, 0, 0, 732, 136001, 2.09, "2026/08/23 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (136101, 0, "2025/11/03 11:59:59", "さくら", "【物理】中衛で不運に抗い歌い続けるゾンビィアイドル。\n一度倒れても立ち上がり、ＴＰを糧に強化されるスキルの\nダメージと味方の支援で、サガの心をアストルムに刻む。", 0, 136101, 1, 0, "サクラ", 0, 3, 136101, 0, 0, 432, 136101, 1.74, "2025/10/24 12:00:00", 1, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (136201, 3, "2030/12/31 15:00:00", "なーな", "【物理】前衛でダメダメでも逃げず戦うアルミラージ娘。\n最も近くの味方に強化や行動不能無効の付与、回復を行い\n敵の注意をそらすことで、過酷な世界を生き延びる。", 0, 136201, 1, 0, "ナーナ", 3, 3, 136201, 0, 0, 198, 136201, 2.09, "2025/11/14 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (136301, 35, "2026/07/15 11:59:59", "みそら", "【魔法】後衛で、シゲキ的な聖夜に鼓動高鳴る溌溂少女★\n【イルミネーションバレット】を消費して味方を支援し、\n40消費後は追加の範囲攻撃やバフでキュン★を届ける。", 0, 136301, 2, 0, "ミソラ（クリスマス）", 54, 3, 136301, 0, 0, 655, 136301, 2.09, "2026/07/03 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (136401, 7, "2026/07/15 11:59:59", "ゆい", "【魔法】中衛で、騎士の隣に一歩踏み出す聖夜の魔法士。\n敵の注目を集めながら攻防支援を行い【聖夜の愛慕】が\n高まると、ＴＰ支援やダメージカットで優しく包み込む。", 0, 136401, 2, 0, "ユイ（クリスマス）", 21, 3, 136401, 0, 0, 382, 136401, 1.84, "2026/07/03 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (136501, 5, "2026/08/23 11:59:59", "しずる", "【物理】前衛で、凛然と立ちはだかる新年のお姉ちゃん。\n挑発と行動不能無効で攻撃を鮮やかに捌き、状況に応じて\n物理・魔法を自在に操り、弟くんへの愛を見せつける。", 0, 136501, 1, 0, "シズル（ニューイヤー）", 0, 3, 136501, 0, 0, 151, 136501, 2.09, "2026/08/15 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (136601, 1, "2030/12/31 15:00:00", "めどぅーさ", "", 0, 136601, 0, 0, "メドゥーサ", 1, 1, 0, 0, 0, 0, 0, 0.0, "2015/04/01 15:00:00", 0, 0, 0, 0, 0, 0);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (136701, 8, "2030/12/31 15:00:00", "らびりすた", "", 0, 136701, 0, 0, "ラビリスタ（アルファ）", 1, 3, 0, 0, 0, 0, 0, 0.0, "2015/04/01 15:00:00", 0, 0, 0, 0, 1, 0);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (136801, 7, "2030/12/31 15:00:00", "らんふぁ", "", 0, 136801, 0, 0, "ランファ（儀装束）", 1, 3, 0, 0, 0, 0, 0, 0.0, "2015/04/01 15:00:00", 0, 0, 0, 0, 1, 0);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (136901, 3, "2030/12/31 15:00:00", "るるぃ", "【物理】中衛でうねる、珍味な触手の小姓見習いタコ娘。\nＴＰ回復、継続ＨＰ回復、バリアで味方をもてなし、多様\nな弱体効果を与える自慢の墨で、敵を真っ黒に染める。", 0, 136901, 1, 0, "ルルィ", 0, 3, 136901, 0, 0, 409, 136901, 2.09, "2026/05/22 12:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (137101, 8, "2030/12/31 15:00:00", "にのん", "【魔法】中衛で陽光の下、煌く水面を共に駆けるシノビ。\n【水遁の印】を自らの攻撃力へと変え、束縛フィールドと\n水遁の術で最も遠い敵とその周囲に速やかな天誅を下す。", 0, 137101, 2, 0, "ニノン（サマー）", 47, 3, 137101, 0, 0, 566, 137101, 2.09, "2025/08/15 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (137201, 2, "2030/12/31 15:00:00", "らびりすた", "", 0, 137201, 0, 0, "ラビリスタ", 2, 3, 0, 0, 0, 0, 0, 0.0, "2015/04/01 15:00:00", 0, 0, 0, 0, 0, 0);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (137301, 2, "2030/12/31 15:00:00", "かのん", "", 0, 137301, 0, 0, "カノン", 1, 3, 0, 0, 0, 0, 0, 0.0, "2015/04/01 15:00:00", 0, 0, 0, 0, 1, 0);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (137401, 7, "2026/06/22 11:59:59", "かすみ", "【魔法】後衛で、聖なる光に包まれ微笑み祈るシスター。\n攻防デバフを操り【真実の導き】が集まると最大３キャラ\nへの攻撃が最も魔防の低い敵を追及し、真理を照らす。", 0, 137401, 2, 0, "カスミ（シスター）", 21, 3, 137401, 0, 0, 688, 137401, 2.09, "2026/06/10 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (137501, 1, "2030/12/31 15:00:00", "あいら", "", 0, 137501, 0, 0, "アイラ", 1, 3, 0, 0, 0, 0, 0, 0.0, "2015/04/01 15:00:00", 0, 0, 0, 0, 1, 0);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (137601, 7, "2026/08/26 11:59:59", "こっころ", "【魔法】後衛で、主さまを想い“進化”した嚮導の巫女。\n極大ダメージのＵＢで敵を穿ち、【進化超越】の権能によ\nって、味方のバフやダメージを、限界を超え成長させる。", 0, 137601, 2, 0, "コッコロ（嚮導幼君）", 0, 3, 137601, 0, 0, 733, 137601, 2.09, "2026/08/23 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (137801, 7, "2030/12/31 15:00:00", "ゆきの", "", 0, 137801, 0, 0, "ユキノ", 1, 3, 0, 0, 0, 0, 0, 0.0, "2015/04/01 15:00:00", 0, 0, 0, 0, 1, 0);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (137901, 8, "2026/08/23 11:59:59", "りの", "【魔法】後衛で絵馬に込めた想いを胸に抱く晴れ着の妹。\nクリティカル時に威力が上がる矢で敵を撃ち抜き、味方\n全体への攻撃支援や継続ＴＰ回復で厄を払い福を届ける。", 0, 137901, 2, 0, "リノ（ニューイヤー）", 8, 3, 137901, 0, 0, 684, 137901, 2.09, "2026/08/15 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (138001, 0, "2026/09/22 11:59:59", "うぁいおれっと", "【物理】前衛から慈愛の心で冥府を包む彼岸の屍姫。\nＵＢは敵全体を呑み込む割合ダメージを与え、【冥海の加\n護】を消費して味方の攻防ダウン効果までも禊ぎ清める。", 0, 138001, 1, 0, "ヴァイオレット（イサナミ）", 0, 3, 138001, 0, 0, 154, 138001, 2.09, "2026/09/10 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (138101, 0, "2026/09/22 11:59:59", "らいらえる", "【魔法】後衛で、民とハーモニーを奏でる天使の姫君。\nステータスアップ効果を受け【エクスマキナ】が溜まると\n行動パターンが変化し、絶え間ない弓撃で神威を示す。", 0, 138101, 2, 0, "ライラエル（パルフェクト）", 0, 3, 138101, 0, 0, 729, 138101, 2.09, "2026/09/10 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (138201, 0, "2026/09/22 11:59:59", "ねふぃーねら", "【物理】中衛から怯懦を退け、万魔を率する煉獄の鉄媛。\n千変万化の躰は行動速度アップを始めとする多彩な支援と\nすべての敵の弱体を両立し、天地万象を掌の内に収める。", 0, 138201, 1, 0, "ネフィ＝ネラ（鬼面仏心）", 0, 3, 138201, 0, 0, 502, 138201, 2.09, "2026/09/10 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (138301, 0, "2026/08/26 11:59:59", "ぺこりーぬ", "【物理】前衛で女神の血脈と矜持を揮う全力全開の王女。\n物理攻撃力の高い味方を【裁定の盾】で庇い、自身は圧倒\n的な防御とＨＰ回復で前線に立ち幸せな食卓を守り抜く。", 0, 138301, 1, 0, "ペコリーヌ（アストライア）", 0, 3, 138301, 0, 0, 142, 138301, 2.09, "2026/08/23 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (138601, 1, "2030/12/31 15:00:00", "さくら", "", 0, 138601, 0, 0, "サクラ", 1, 3, 0, 0, 0, 0, 0, 0.0, "2015/04/01 15:00:00", 0, 0, 0, 0, 1, 0);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (138701, 7, "2026/10/15 11:59:59", "わかな", "【物理】中衛で恥じらいながらも激戦に飛び込む桃闘者。\n味方を【スパイクシール】で守りつつ、自身は物理防御力\nダウンで敵を切り崩し、鍛え上げた桃尻を存分に振るう。", 0, 138701, 1, 0, "ワカナ（ウィンター）", 55, 3, 138701, 0, 0, 539, 138701, 2.09, "2026/09/30 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (138801, 8, "2026/10/15 11:59:59", "しおり", "【物理】中衛で、過酷なお尻の世界を生き抜く桃闘者。\n攻防ダウンを併せ持つＵＢを矢継ぎ早に放ち、ステータス\nダウン効果で付与する【魅惑の矢】で敵を骨抜きにする。", 0, 138801, 1, 0, "シオリ（ウィンター）", 8, 3, 138801, 0, 0, 571, 138801, 2.09, "2026/09/30 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (138901, 4, "2026/04/10 11:59:59", "ぐれいす", "【物理】中衛で、妖しく跳ねるバニーの幽霊守護騎士。\n物理攻撃力を代償に物理クリダメを極大アップし、【ブラ\nックうさ耳】で油断した敵の虚を突き、御首を頂戴する。", 0, 138901, 1, 0, "グレイス（バニー）", 0, 3, 138901, 0, 0, 429, 138901, 2.09, "2026/03/31 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (139001, 7, "2026/04/22 11:59:59", "きょうか", "【魔法】後衛で、破滅の運命にあらがうお嬢様？優等生。\n【呪いの鎖】の溢れる魔力で魔防デバフやＴＰ、速度支援\nを行うが、限界を迎えると永久的狂気に陥ってしまう。", 0, 139001, 2, 0, "キョウカ（ゴシック）", 7, 3, 139001, 0, 0, 816, 139001, 2.09, "2026/04/10 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (139101, 0, "2026/08/26 11:59:59", "きゃる", "【魔法】後衛で、天の星を瞳に映し、仲間と進む黒猫娘。\n敵全体を激烈に弱体化させながら、【千里真眼】状態時に\n未来を視通す能力で仲間をあらゆる脅威から遠ざける。", 0, 139101, 2, 0, "キャル（覇瞳天星）", 0, 3, 139101, 0, 0, 770, 139101, 2.09, "2026/08/23 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (139201, 0, "2030/12/31 15:00:00", "みほ", "【魔法】中衛で臨機応変に作戦を指揮する戦車道の乙女。\n召喚したボコが敵の攻撃を引き付けている間に、周囲の\n味方の攻撃、回復支援によって、全員での勝利を目指す。", 0, 139201, 2, 1, "ミホ（ガルパン）", 0, 1, 139201, 0, 0, 486, 139201, 2.09, "2026/04/30 12:00:00", 1, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (139301, 0, "2026/05/22 11:59:59", "まほ", "【物理】後衛から必中の一射で敵を貫く西住流の継承者。\n【榴弾】を装填した状態のＵＢは、防御力を無視する火傷\nフィールドを発生させ、圧倒的な戦力差で敵を蹂躙する。", 0, 139301, 1, 0, "マホ（ガルパン）", 0, 3, 139301, 0, 0, 700, 139301, 2.09, "2026/04/30 12:00:00", 1, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (139401, 0, "2026/05/22 11:59:59", "えりか", "【物理】中衛から迅速な強襲で戦局を切り拓く双剣使い。\nバトル開始直後からＴＰを消費する強力なスキルの連撃で\n敵の防御力を一気に下げ、敵陣深くまで浸透突破する。", 0, 139401, 1, 0, "エリカ（ガルパン）", 0, 3, 139401, 0, 0, 322, 139401, 1.04, "2026/05/11 12:00:00", 1, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (139501, 0, "2026/06/10 11:59:59", "りり", "【魔法】中衛で、寄る辺無き魂を繋ぎ導く清廉の戦乙女。\nダメージと共に敵の魔防を削ぎ、継続ダメージを与える聖\n浄の光が戦乙女の聖槍を降り注がせ、敵を清め祓う。", 0, 139501, 2, 0, "リリ（ヴァルキュリア）", 0, 3, 139501, 0, 0, 453, 139501, 2.09, "2026/05/31 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (139601, 2, "2026/06/30 11:59:59", "くりあ", "【魔法】前衛で、奇跡により魂の疵を癒す浄罪の戦乙女。\n味方を物理攻撃から堅牢に守り、継続ダメージを与える聖\n浄の光を敵に浴びせ、戦乙女の聖槍による天罰を下す。", 0, 139601, 2, 0, "クリア（ヴァルキュリア）", 0, 3, 139601, 0, 0, 150, 139601, 2.09, "2026/06/22 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (139701, 0, "2026/06/22 11:59:59", "ぷれしあ", "【魔法】中衛で、正義の光で邪な魂を祓う勧善の戦乙女。\n多彩な支援効果で味方を支え、継続ダメージを与える聖浄\nの光が戦乙女の聖槍を喚び寄せ、悪をこらしめる。", 0, 139701, 2, 0, "プレシア（ヴァルキュリア）", 0, 3, 139701, 0, 0, 500, 139701, 2.09, "2026/06/10 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (139801, 0, "2026/08/26 11:59:59", "しぇふぃ", "【物理】中衛で兄妹の絆と不撓の心で覚醒した氷竜少女。\n個も群も薙ぎ払うＵＢと、【氷竜超克】状態時に発生する\n追撃状態で敵を咬断し、大切な人と歩む未来を切り拓く。", 0, 139801, 1, 0, "シェフィ（ヴァードラッヘ）", 0, 3, 139801, 0, 0, 386, 139801, 2.09, "2026/08/23 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (139901, 55, "2026/07/15 11:59:59", "るいずまりー", "【魔法】後衛で、大人の階段を上りたい水着の錬金術師。\n発動回数で性能が上昇するＵＢとスキルで、調和状態の\n付与と攻防たゆまぬ支援を行い、ひと夏の思い出を創る。", 0, 139901, 2, 0, "ルイズマリー（サマー）", 55, 3, 139901, 0, 0, 757, 139901, 2.09, "2026/07/03 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (140001, 54, "2026/07/31 11:59:59", "くれじった", "【魔法】後衛で、リゾート建設に奔走する水着の女商人。\n初回発動時に強力な攻撃支援と一定時間魔攻・物防・魔防\nダウンを無効化するスキルで、豪奢に味方を駆り立てる。", 0, 140001, 2, 0, "クレジッタ（サマー）", 54, 3, 140001, 0, 0, 730, 140001, 2.09, "2026/07/15 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (140101, 54, "2026/08/15 11:59:59", "ふぶき", "【物理】中衛であざとくラヴを奪う超天才びしょーじょ。\n毒と火傷で弱らせた敵をあざ笑うかのように、自分と\n先頭の味方へＴＰ回復や行動不能無効を付与し強化する。", 0, 140101, 1, 0, "フブキ（サマー）", 54, 3, 140101, 0, 0, 376, 140101, 2.09, "2026/07/31 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (140201, 43, "2030/12/31 15:00:00", "うぁんぴぃ", "【魔法】中衛でけんぞくとラヴを集めるつよつよ吸血姫。\nスキルでＴＰを吸収し、【チャームスローブ】を消費して\n放つＵＢは、ほとばしるカワいさで敵を骨抜きにする。", 0, 140201, 2, 0, "ヴァンピィ（サマー）", 43, 3, 140201, 0, 0, 582, 140201, 2.09, "2026/08/15 12:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (140301, 0, "2026/08/26 11:59:59", "てぃあ", "【魔法】後衛から、中立で平等とうそぶく認識の修正者。\n敵の認識を乱して弱体効果を付与し、一方で味方が受ける\n混乱、誘惑状態を無効化しお気に入りの彼に肩入れする。", 0, 140301, 2, 0, "ティア", 0, 3, 140301, 0, 0, 744, 140301, 2.09, "2026/08/23 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (140401, 0, "2026/09/22 11:59:59", "りーざ", "【物理】後衛で、答えを求め彷徨うダークエルフの咎人。\nＵＢで放つ矢の呪いは二度重なれば呪詛、三度重なれば\n強烈な割合ダメージとなり、立ちはだかる敵を殺める。", 0, 140401, 1, 0, "リーザ", 0, 3, 140401, 0, 0, 780, 140401, 2.09, "2026/09/10 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (140501, 0, "2026/09/10 11:59:59", "うるむ", "【物理】中衛で、愛する者たちのため本意気を放つ妹竜。\n【決意の流星】を溜め覚醒すると、攻撃スキルが再発動し\nさらに味方の火力を引き上げ、渦炎で敵を灰燼に変える。", 0, 140501, 1, 0, "ヴルム（ヴァルムドラッヘ）", 0, 3, 140501, 0, 0, 396, 140501, 2.09, "2026/08/31 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (140601, 0, "2030/12/31 15:00:00", "くろーちぇ", "【物理】中衛から必殺クローで敵全体を圧潰するロボ娘。\n自分へのバフと敵へのデバフで【水陸可変ブースター】が\n起動し、高頻度のＵＢでダメージの大渦潮を巻き起こす！", 0, 140601, 1, 0, "クローチェ（サブマリン）", 0, 3, 140601, 0, 0, 400, 140601, 2.09, "2026/09/22 12:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (140701, 0, "2026/10/09 11:59:59", "されん", "【物理】中衛で、敵影に照準を定める戦場のサレンママ。\n７種以上の弱体効果があれば更に効果が増すスキルで敵の\n装甲に風穴を開け、臨機応変の戦術で窮地を逆手に取る。", 0, 140701, 1, 0, "サレン（ガンナー）", 0, 3, 140701, 0, 0, 431, 140701, 2.09, "2026/09/30 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (140801, 0, "2026/10/23 11:59:59", "あめす", "【魔法】中衛で、まばゆい弾丸の雨を降らす銃装の妖精。\n一定回数ダメージを与えるたび割合ダメージを発生させ、\n【ペタロ】で敵からの攻撃をひらりと躱し、無効化する。", 0, 140801, 2, 0, "アメス（ガンナー）", 0, 3, 140801, 0, 0, 512, 140801, 2.09, "2026/10/09 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (141401, 1, "2030/12/31 15:00:00", "しずる", "", 0, 141401, 0, 0, "シズル（ニューイヤー）", 1, 1, 0, 0, 0, 0, 0, 0.0, "2015/04/01 15:00:00", 0, 0, 0, 0, 0, 0);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (141501, 0, "2030/12/31 15:00:00", "うぁいおれっと", "", 0, 141501, 0, 0, "ヴァイオレット（イサナミ）", 1, 3, 0, 0, 0, 0, 0, 0.0, "2015/04/01 15:00:00", 0, 0, 0, 0, 0, 0);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (141601, 4, "2030/12/31 15:00:00", "ぐれいす", "", 0, 141601, 0, 0, "グレイス（バニー）", 1, 3, 0, 0, 0, 0, 0, 0.0, "2015/04/01 15:00:00", 0, 0, 0, 0, 1, 0);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (143001, 0, "2030/12/31 15:00:00", "るいずまりー", "", 0, 143001, 0, 0, "ルイズマリー", 1, 3, 0, 0, 0, 0, 0, 0.0, "2015/04/01 15:00:00", 0, 0, 0, 0, 0, 0);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (170101, 34, "2030/12/31 15:00:00", "じーた", "【物理】前衛で、先手必勝の大技を繰り出す騎空士。\nスキルによるＴＰ回復は、ユニオンバーストの発動を早め\nバトルの序盤から敵前衛に大ダメージを与える。", 4, 170101, 1, 0, "ジータ", 34, 3, 170101, 0, 0, 245, 105701, 1.965, "2015/04/01 15:00:00", 0, 0, 0, 0, 0, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (180101, 0, "2026/08/26 11:59:59", "ひより", "【物理】前衛で炎翼を背に敵を粉砕する、陽気な元気娘。\n戦いが続く程に自身の攻撃能力を強めるスキルを操り、\n高めた力で放つ超爆の一撃は、あらゆる敵を塵と化す。", 7, 180101, 1, 0, "ヒヨリ（プリンセス）", 0, 3, 180101, 0, 0, 199, 180101, 1.62, "2026/08/23 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (180201, 0, "2026/08/26 11:59:59", "ゆい", "【魔法】後衛から極大魔法で敵を滅する願いの魔法士。\nＴＰを回復しつつ攻撃力を累積アップする補助スキルで\n自身の力を高め、強力な範囲攻撃を放ち敵を一掃する。", 1, 180201, 2, 0, "ユイ（プリンセス）", 0, 3, 180201, 0, 0, 767, 180201, 1.92, "2026/08/23 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (180301, 0, "2026/08/26 11:59:59", "れい", "【物理】中衛で風刃を従え激戦を流麗に征く嵐翼の剣士。\n敵が多い程に効果が高まる自己強化スキルで、自身を奮い\n立たせ、強力な範囲攻撃スキルで一切の敵を鏖滅する。", 7, 180301, 1, 0, "レイ（プリンセス）", 0, 3, 180301, 0, 0, 377, 180301, 1.965, "2026/08/23 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (180401, 0, "2026/08/26 11:59:59", "ぺこりーぬ", "【物理】前衛で、攻防共に絶大な力を誇る腹ペコ王女。\nＨＰが多い時は爆発的な攻撃力で、いかなる敵をも屠り、\nＨＰが減ると自己回復能力を得て、鉄壁の護りを見せる。", 1, 180401, 1, 0, "ペコリーヌ（プリンセス）", 0, 3, 180401, 0, 0, 155, 180401, 1.965, "2026/08/23 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (180501, 0, "2026/08/26 11:59:59", "こっころ", "【物理】中衛で、絶大な補助スキルを繰出す純白の巫女。\n味方の攻撃力とクリティカルダメージを強化しつつ、\n二つの全体回復スキルで味方を堅固に守護し勝利へ導く。", 1, 180501, 1, 0, "コッコロ（プリンセス）", 0, 3, 180501, 0, 0, 555, 180501, 2.14, "2026/08/23 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (180601, 0, "2026/08/26 11:59:59", "きゃる", "【魔法】後衛で、極大魔法を操り敵を討つ姫装の猫娘。\n回復や補助を兼ねた各攻撃スキルを駆使し戦況を整え、\n極大威力のユニオンバーストを撃ち込み敵を燼滅する。", 1, 180601, 2, 0, "キャル（プリンセス）", 0, 3, 180601, 0, 0, 747, 180601, 1.92, "2026/08/23 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (180701, 0, "2026/08/26 11:59:59", "はつねしおり", "【物理】後衛から、真の絆の力を発揮する仲良し姉妹。\n敵の数が増えるほど威力が高まる攻撃スキルと、周りの\n味方を強化するスキルを操り、立ち塞がる敵を一掃する。", 1, 180701, 1, 0, "ハツネ＆シオリ", 0, 3, 180701, 0, 0, 732, 180701, 1.75, "2026/08/23 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (180801, 0, "2026/08/26 11:59:59", "みそぎみみきょうか", "【物理】中衛で敵単体に必殺の一撃を放つ仲良しトリオ。\n３人の力を合わせて放つ攻撃は、相手の弱点に合わせて\n物理から魔法攻撃に変化し、どんな強い敵も退治する！", 1, 180801, 1, 0, "ミソギ＆ミミ＆キョウカ", 0, 3, 180801, 0, 0, 465, 180801, 1.5, "2026/08/23 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (180901, 0, "2026/08/26 11:59:59", "あきのされん", "【物理】中衛で背を預けあう最高の好敵手で親友の二人。\n味方の物理攻撃をサポートしつつＨＰとＴＰを継続回復し\nＨＰが多いほど威力が増すＵＢで、共に勝利の道を征く。", 1, 180901, 1, 0, "アキノ＆サレン", 0, 3, 180901, 0, 0, 421, 180901, 2.09, "2026/08/23 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (181001, 0, "2026/08/26 11:59:59", "あんぐれあ", "【魔法】中衛で、魔力共鳴し連撃を放つマナリアの双姫。\nステータスアップ効果を受けると増加する【友情の魔印】\nがスキルを強化し、波長を合わせた炎の魔槍で敵を討つ。", 1, 181001, 2, 0, "アン＆グレア", 0, 3, 181001, 0, 0, 577, 181001, 2.09, "2026/08/23 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (181101, 0, "2026/08/26 11:59:59", "しずるりの", "【物理】中衛でお揃い衣装の、真偽を超えた仲良し姉妹。\n攻守共に味方を支えるシズルと、クリティカル時に強力な\nダメージを与えるリノ、姉妹の絆で困難を跳ね除ける！", 1, 181101, 1, 0, "シズル＆リノ", 0, 3, 181101, 0, 0, 551, 181101, 1.92, "2026/08/23 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (181201, 0, "2026/08/26 11:59:59", "しぇふぃ", "【物理】中衛で新たな力と共に再廻する姫装の氷竜少女。\n環境効果【絶氷】でクリティカルダメージを高め、火力と\n手数を併せ持つ剣技で、再び共に歩むため道を切り開く。", 1, 181201, 1, 0, "シェフィ（プリンセス）", 0, 3, 181201, 0, 0, 368, 181201, 1.92, "2026/08/23 12:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (190801, 1, "2030/12/31 15:00:00", "かりん", "", 0, 190801, 1, 0, "カリン", 1, 1, 0, 0, 0, 0, 0, 0.0, "2015/04/01 15:00:00", 0, 0, 0, 0, 0, 0);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (191201, 1, "2030/12/31 15:00:00", "ぺてるぎうす", "", 0, 191201, 1, 0, "ペテルギウス", 1, 1, 0, 0, 0, 0, 0, 0.0, "2015/04/01 15:00:00", 0, 0, 0, 0, 0, 0);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (191301, 6, "2030/12/31 15:00:00", "かずまさ", "【物理】皆から愛される漁師町のポンコツ漁師。\nユニオンバーストは強力なスタン効果を持つが、\n自身のＨＰが50%以下では尻もちをついてしまう。\n\n・通常攻撃とユニオンバーストを駆使して戦う。", 0, 191301, 1, 0, "カズマサ", 6, 1, 191301, 0, 0, 850, 191301, 2.22, "2015/04/01 15:00:00", 0, 0, 0, 0, 1, 450);
INSERT INTO `v1_ed1b52317ac09b3d790c8feebcfb4fb224b0a1cf16034f167e128f147a09da36` VALUES (191401, 6, "2030/12/31 15:00:00", "こっころ", "", 0, 191401, 0, 0, "コッコロ", 6, 0, 0, 0, 0, 0, 0, 0.0, "2015/04/01 15:00:00", 0, 0, 0, 0, 0, 0);
